return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Khmer','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-12 17:53+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'km','plural-forms'=>'nplurals=1; plural=0;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" បានរក្សាទុក។','"%1$s" created. %2$d template updated.'=>'"%1$s" បានបង្កើត។ %2$d អាប់ដេត។' . "\0" . '','"%s" created.'=>'"%s" បានបង្កើត។','"product" (replaces "article")'=>'"ផលិតផល" (ជំនួស "អត្ថបទ")','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"ព្យាយាម H2 ជា H1 ស្មើគ្នា" (ការកំណត់ → SEO → វិភាគ): បើកវាឡើងនៅពេលដែលប្រធានបទរបស់អ្នកបង្ហាញចូលក្នុង H2 ជំនួស H1។ អ្នកវិភាគលើកទីមួយលើ H2 ទៅ H1 ដើម្បីឲ្យពិន្ទុមិនត្រូវបានប៉ះពាល់ដោយមិនត្រឹមត្រូវ។','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d តួអក្សរ — ល្អ, ខ្ពស់បន្តិចលើសសមាមាត្រល្អ %2$d ប៉ុន្តែនៅក្នុងជួររបស់ %3$d តួអក្សរ។ %4$s','%1$d chars — ideal length. %2$s'=>'%1$d តួអក្សរ — ប្រវែងល្អបំផុត។ %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d តួអក្សរ — ប្រហែលជាត្រូវបានកាត់ចេញក្នុង SERPs (រក្សាទុកក្រោម %2$d)។ %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d តួអក្សរ — ខ្លីពេក (គោលដៅ %2$d–%3$d)។ %4$s','%1$d chars, %2$d words — good title.'=>'%1$d តួអក្សរ, %2$d ពាក្យ — ចំណងជើងល្អ។','%1$d internal, %2$d external.'=>'%1$d ក្នុងសរុប, %2$d ខាងក្រៅ។','%1$d of %2$d image(s) missing alt text.'=>'%1$d រូបភាពក្នុងចំនួន %2$d ខ្វះអត្ថបទ alt។','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d បង្ហោះបានស្លាកសញ្ញា _lf_lang = %2$s។' . "\0" . '','%1$d translated, %2$d skipped.'=>'%1$d បានបកប្រែ, %2$d បានរំលង។','%1$d words — below recommended minimum of %2$d.'=>'%1$d ពាក្យ — ក្រោមលេខអប្បបរមាដែលបានណែនាំ %2$d។','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d ពាក្យ — ខ្លឹមសារស្តើងខ្លាំង។ សូមពិចារណាពង្រីកឱ្យដល់យ៉ាងហោចណាស់ %2$d ពាក្យ។','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d បានបកប្រែរួចហើយ — <a href="#" class="lf-force-translate">បង្វិលបកប្រែម្ដងទៀត</a>','%d external link(s), no internal links.'=>'%d តំណភ្ជាប់ខាងក្រៅ ដោយគ្មានតំណភ្ជាប់ខាងក្នុង។','%d external link(s), no internal links. Add internal links to related content.'=>'%d តំណខាងក្រៅ, គ្មានតំណក្នុង។ បន្ថែមតំណក្នុងទៅមាតិកាដែលពាក់ព័ន្ធ។','%d H1 tags found — a page should have exactly one H1.'=>'រកឃើញ %d ស្លាក H1 — ទំព័រត្រូវមាន H1 មួយតែមួយ។','%d image(s), all have alt text.'=>'%d រូបភាព, មានអត្ថបទ alt ទាំងអស់។','%d label(s) translated.'=>'បានបកប្រែ %d ស្លាក។','%d language not yet linked'=>'ភាសា %d មិនទាន់ភ្ជាប់ទេ' . "\0" . '','%d link updated.'=>'%d តំណបានអាប់ដេត។' . "\0" . '','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'មិនអាចលុបឯកសារភាសា %d បានដោយស្វ័យប្រវត្តិ (DISALLOW_FILE_MODS ត្រូវបានកំណត់)។ លុបដោយដៃតាមរយៈម៉ាស៊ីនមេរបស់អ្នកឬ WP-CLI: wp language core uninstall <locale>' . "\0" . '','%d locale file removed.'=>'ឯកសារភាសា %d ត្រូវបានលុប។' . "\0" . '','%d locale pack installed.'=>'%d កញ្ចប់ locale ត្រូវបានដំឡើង។' . "\0" . '','%d navigation reference updated.'=>'%d ការចាប់យោងនាវីហ្គេសិនបានអាប់ដេត។' . "\0" . '','%d part reference updated.'=>'%d ការចាប់យោងផ្នែកបានអាប់ដេត។' . "\0" . '','%d post'=>'%d បង្ហោះ' . "\0" . '','%d rule registered'=>'ច្បាប់  %d បានចុះបញ្ជី' . "\0" . '','%d template repaired.'=>'បានជួសជុលគំរូ %d។' . "\0" . '','%d term(s) translated.'=>'បានបកប្រែ %d ពាក្យ។','%d words.'=>'%d ពាក្យ។','%s Archive'=>'សៀវភៅប្រចាំ: %s','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s មានសកម្មភាពហើយបានបញ្ចេញ Schema.org JSON-LD។ Lingua Forge បានបិទការបញ្ចេញ schema ដើម្បីបញ្ឈប់ភាពផ្ទុយគ្នា។ ផ្ទុយពី Open Graph — ដែល LF បន្ថែម og:locale នៅលើផ្នែក plugin មួយទៀត — schema មិនអាចបន្ថែមបានច្បាស់លាស់: JSON-LD ផ្ទុកឡើងជាស្ទួនឬផ្ទុកឡើងជាច្រើនបង្កើតកំហុស។ បិទ schema នៅក្នុង plugin ដែលបានរកឃើញ ប្រសិនបើអ្នកចង់ឲ្យ LF គ្រប់គ្រងទិន្នន័យរចនា។','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s មានសកម្មភាព ហើយបង្កើត sitemap របស់ខ្លួន។ សitemap នេះផ្សេងពី LF។ ទាំងពីរត្រូវបានដាក់ស្នើទៅ Google Search Console: sitemap SEO បង្ហាញមាតិការបស់អ្នក; sitemap LF បន្ថែមតំណភ្ជាប់ជាច្រើនភាសា។ សitemap LF ត្រូវបានប្រកាសក្នុង robots.txt ដោយស្វ័យប្រវត្តិ។','(active)'=>'(សកម្ម)','(avg %.1f hits/block)'=>'(មធ្យម %.1f ចុច/ប្លុក)','(avg %.1f hits/entry)'=>'(មធ្យម %.1f ចុច/ចូល)','(classic theme)'=>'(ប្រធានបទបុរាណ)','(disabled)'=>'(បិទ)','(FSE / block theme)'=>'(FSE / ប្រធានបទប្លុក)','(no title) #%d'=>'(មិនមានចំណងជើង) #%d','(partial)'=>'(ផ្នែកខ្លះ)','(server/FPM timeout still applies)'=>'(ការរង់ចាំម៉ាស៊ីនបម្រើ/FPM នៅតែមានប្រសិទ្ធភាព)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} មិនមានតំណភ្ជាប់ដែលអាចជួសជុលបាន — សូមស្កេនឡើងវិញដើម្បីស៊ើបអង្កេត)','.txt file(s) in the directory'=>'.txt ឯកសារ(ៗ) នៅក្នុងថតឯកសារ','/ 100'=>'/ 100','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — រកមិនឃើញ H2 ឬ H3 ចំណងជើងរង។ ការបន្ថែម H2s ធ្វើឱ្យប្រសើរឡើងនូវរចនាសម្ព័ន្ធ។','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'H1 1 ✓ — គ្មានចំណងជើងរង H2 (អាចអនុញ្ញាតសម្រាប់ប្រភេទមាតិកានេះ)។','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — គ្មាន H2, ប៉ុន្តែមាន %d ចំណងជើងរង H3 (ឧទាហរណ៍, ចំណងជើង accordion/details)។ រចនាសម្ព័ន្ធអាចទទួលយកបាន។','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — មាតិកាសង្ខេប (%d ប្រសាទ), មិនចាំបាច់មានចំណងជើងរង។','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3។','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d គំរូដែលបានបញ្ជាក់ទីតាំងស្ថានភាពក្នុងមូលដ្ឋានទិន្នន័យពីប្រធានបទ &#8220;%2$s&#8221; ត្រូវបានរក្សាទុក ប៉ុន្តែបច្ចុប្បន្នមិនសកម្ម។ ពួកវានឹងត្រឡប់មកសកម្មវិញ ប្រសិនបើអ្នកបើកប្រើប្រធានបទនោះវិញ។ ដើម្បីផ្ទេរវិចារណារបស់អ្នកទៅប្រធានបទថ្មី សូមបង្កើតឡើងវិញតាមរយៈ <strong>ការកំណត់ → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> តំណភ្ជាប់ដែលអាចជួសជុលដោយស្វ័យប្រវត្តិ','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> តំណភ្ជាប់ដែលត្រូវការការត្រួតពិនិត្យដោយដៃ','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> ផ្លូវចាស់ៗ','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> បញ្ហាកំណត់គំរូ','_lf_lang Coverage'=>'ការគ្រប់គ្រង _lf_lang','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'មានឯកសារ robots.txt រាងរាងនៅក្បែរមូលដ្ឋាន។ WordPress\'s virtual robots.txt — និង LF\'s Sitemap: filter — ត្រូវបានរំលង។ សitemap LF មិនបានប្រកាសទៅកាន់ម៉ាស៊ីនស្វែងរក។','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'ទទួលយកតែឯកសារ .mo ដែលបានបញ្ចូល។ ឈ្មោះឯកសារត្រូវតែអនុលោមលំនាំ {textdomain}-{locale}.mo។ ការផ្ទុកឯកសារដែលមានឈ្មោះដូចគ្នានឹងជំនួសឯកសារដែលមានស្រាប់។','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'ការចូលប្រើត្រូវបានហាមឃាត់ — គណនីរបស់អ្នកអាចត្រូវបានផ្អាក ឬកូនសោអវត្តមានសិទ្ធិចាំបាច់។','Action'=>'សកម្មភាព','active'=>'សកម្ម','Active Languages'=>'ភាសាដែលមានសកម្មភាព','Active languages'=>'ភាសាដែលសកម្ម','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'ភាសាដែលសកម្ម៖ បន្ថែមភាសាណាមួយដែលអ្នកចង់គាំទ្រ។ ភាសាEach gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.','Active Plugins'=>'កម្មវិធីផ្លាកសញ្ញាដែលដំណើរការ','Active preset'=>'ការកំណត់ជាមុនសកម្ម','Active Provider'=>'អ្នកផ្គត់ផ្គង់ដែលបានប្រើប្រាស់','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'អ្នកផ្គត់ផ្គង់សកម្ម, កូនសោដែលបានកំណត់រចនា, ជម្រើសស្រទាប់ម៉ូដែល, ការកំណត់ជាមុន, និងបរិមាណប្រចាំថ្ងៃ។','Active theme'=>'ប្រធានបទសកម្ម','Active: %s.'=>'សកម្ម: %s។','Add entry'=>'បន្ថែមចុះបញ្ជី','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'បន្ថែមការណែនាំដើម្បីកែលម្អសេចក្ដីព្រាង — ឧ. ធ្វើឲ្យខ្លីជាង, បន្ថែមផ្នែកសេចក្ដីសង្ខេប, ប្រើសមាជិកផ្លូវការជាង, រួមបញ្ចូលផ្នែកសំណួរញឹកញាប់…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'បន្ថែមការណែនាំដើម្បីធ្វើឱ្យសេចក្ដីព្រាងប្រសើរឡើង — ឧ. ធ្វើឱ្យខ្លីស្រួល, បន្ថែមផ្នែកសន្និដ្ឋាន, ប្រើសម្លេងផ្លូវការជាងមុន…','Add key →'=>'បន្ថែមកូនសោ →','Add new entry'=>'បន្ថែមចុះបញ្ជីថ្មី','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'បន្ថែមពាក្យមួយក្នុងមួយជួរ។ ទាំងពាក្យប្រភព និងការបង្ហាញគោលត្រូវតែមាន។ គូភាសាបញ្ជាក់ថាការងារប្រែសម្រួលណាដែលការទាមទារនេះអាចប្រើបាន។','Add Sitemap directive to robots.txt'=>'បន្ថែមសេចក្តីណែនាំ Sitemap ទៅក្នុង robots.txt','Add the following line to your robots.txt manually:'=>'បន្ថែមបន្ទាត់ខាងក្រោមទៅក្នុង robots.txt ដោយដៃ៖','Add WooCommerce product tags to Open Graph output'=>'បន្ថែមស្លាកផលិតផល WooCommerce ទៅក្នុងការបង្ហាញ Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'បន្ថែមតំណទៅទំព័រផ្ទះដើម្បីឲ្យភ្ញៀវអាចរកមើលជាភាសារបស់ពួកគេ។','Administrators only (manage_options)'=>'អ្នកគ្រប់គ្រងតែប៉ុណ្ណោះ (គ្រប់គ្រងជម្រើស)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'បន្ទាប់ពីផ្លាស់ប្តូរភាសាចម្បង, សូមលុប permalinks (ផ្នែកខាងក្រោម) ដើម្បីអាប់ដេត URL routing។','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'បន្ទាប់ពីផ្លាស់ទីការកំណត់រចនាសម្ព័ន្ធ URL (ផ្លូវបន្ថែម ↔ ឧបករណ៍បណ្តាញរង), តែងតែចូលទៅកាន់ ការកំណត់ → Permalinks ហើយចុចរក្សាទុកការផ្លាស់ប្តូរ ដើម្បីបំលែងច្បាប់សរសេរ។','AI analysis failed. Please try again.'=>'ការវិភាគ AI បានបរាជ័យ។ សូមព្យាយាមម្តងទៀត។','AI Behaviour Preset'=>'កំណត់សេចក្តីប្រើប្រាស់ AI','AI cache cleared. %d entry was removed.'=>'Cache AI ត្រូវបានសម្អាត។ %d ធាតុត្រូវបានយកចេញ។' . "\0" . '','AI Configuration'=>'ការកំណត់ AI','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'លក្ខណៈពិសេស AI គឺជាជម្រើស។ ការបញ្ជូនភាសា, hreflang, អ្នកផ្លាស់ប្តូភាសា, និងប្រព័ន្ធក្រុមប្រែសម្រួលទាំងអស់ដំណើរការដោយគ្មានអ្នកផ្គត់ផ្គង់បានកំណត់។','AI Limits & Security'=>'កំណត់ AI និងសុវត្ថិភាព','AI Provider'=>'ក្រុមហ៊ុនផ្តល់សេវាកម្ម AI','AI provider returned an empty response.'=>'អ្នកផ្គត់ផ្គង់ AI បានផ្តល់ចម្លើយទទេ។','AI Provider Tab'=>'ផ្ទាំងអ្នកផ្គត់ផ្គង់ AI','AI Recommendations'=>'ការណែនាំ AI','AI returned an unexpected response format. Please try again.'=>'AI បានផ្តល់ចម្លើយមិនច្បាស់។ សូមព្យាយាមម្តងទៀត។','AI translation and batch analysis may time out. Recommend 120s or more.'=>'ការប្រែសម្រួល AI និងការវិភាគជាក្រុមអាចប្រើពេលច្រើន។ ផ្តល់អនុសាសន៍ 120 វិនាទី ឬច្រើនជាងនេះ។','AI Usage'=>'ការប្រើប្រាស់ AI','AI Usage & Cache'=>'ការប្រើប្រាស់ AI & Cache','AI Usage & Cache Tab'=>'ផ្ទាំងការប្រើប្រាស់ AI & Cache','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'មានគោលបំណងសម្រាប់ 120–160 តួអក្សរ។ ទុកវាឲ្យទទេដើម្បីប្រើការបង្ហាញជាជម្រើស។','All labels already translated.'=>'ស្លាកទាំងអស់បានបកប្រែរួចហើយ។','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'ម៉ាស៊ីនស្វែងរកចម្បងទាំងអស់ — Google, Bing, និង Yandex — ស្វែងរកសitemap ដោយស្វ័យប្រវត្តិ តាមរយៈសេចក្តីណែនាំ Sitemap: នៅក្នុង robots.txt។ មិនចាំបាច់សកម្មភាពដៃ។ ប៊ូតុងខាងក្រោមផ្ញើ ping យ៉ាងភ្លាមៗ ដើម្បីឲ្យម៉ាស៊ីនស្វែងរកស្ទួចសitemap ឥឡូវនេះ ជាជាងការរង់ចាំការត្រួតពិនិត្យ robots.txt បន្ទាប់។','All published posts have a _lf_lang value. No gaps detected.'=>'បង្ហោះប្លុកទាំងអស់មានតម្លៃ _lf_lang។ មិនមានចន្លោះ។','All template metadata is already up to date.'=>'មេតាដាតាខ្លួនគំរូទាំងអស់បានធ្វើឱ្យទាន់សម័យរួចហើយ។','All time'=>'គ្រប់ពេលវេលា','All types'=>'គ្រប់ប្រភេទ','Allow editors to lock individual blocks'=>'អនុញ្ញាតឲ្យអ្នកកែសម្រួលចាក់សោ Block ផ្ទាល់ខ្លួន','Allow Gutenberg template-editing mode on post screens'=>'អនុញ្ញាតឲ្យប្រើរបៀបកែសម្រួលគំរូ Gutenberg នៅលើផ្ទាំងប្រកាស','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'ក៏លុបការចាត់តាំងភាសា, ទំនាក់ទំនងការបកប្រែ, ការពិពណ៌នាមេតា, វចនានុក្រម, និងអង្គចងចាំការបកប្រែ នៅពេលលុបកម្មវិធី','Also generate meta description'=>'បង្កើតការពិពណ៌នាផងដែរ','Alternative (server-side):'=>'ជំនួស (ផ្នែកម៉ាស៊ីនមេ):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'តែងតែចេញ og:locale និង og:locale:alternate តែប៉ុណ្ណោះ។ ប្រើពេលដែល plugin ឬ theme ផ្សេងគ្រប់គ្រងសំណុំ OG ពេញ។','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'តែងតែចេញសំណុំ OG + Twitter Card ពេញ ទោះបីមាន plugin ផ្សេងក៏ដោយ។ ប្រើតែបើ plugin មួយទៀតមិនចេញ OG។','An unknown error occurred.'=>'មានកំហុសមិនស្គាល់កើតឡើង។','Analyse'=>'វិភាគ','Analyse all languages'=>'វិភាគភាសាទាំងអស់','Analyse…'=>'វិភាគ…','Analysis'=>'វិភាគ','Analysis request failed. Please try again.'=>'ការស្នើសុំវិភាគបរាជ័យ។ សូមព្យាយាមម្តងទៀត។','Analyzing…'=>'កំពុងវិភាគ…','and'=>'និង','and set it to one of the active content languages listed above.'=>'ហើយកំណត់វាទៅក្នុងភាសាអត្ថបទសកម្មមួយក្នុងចំណោមភាសាអត្ថបទដែលបានរាយការណ៍ខាងលើ។','Anthropic (Claude)'=>'Anthropic (Claude)','Anthropic Console'=>'កុងសូល Anthropic','any'=>'អ្វីៗ','API calls saved by cache'=>'ការហៅ API ដែលបានរក្សាទុកដោយ cache','API Key'=>'កូនសោ API','API Keys'=>'កូនសោ API','API Response Cache'=>'Cache ចម្លើយ API','API Response Cache setting saved.'=>'ការកំណត់ Cache ចម្លើយ API បានរក្សាទុក។','Appends the following line to your existing robots.txt: %s'=>'បន្ថែមបន្ទាត់ខាងក្រោមទៅក្នុង robots.txt របស់អ្នក: %s','Applied ✓'=>'បានអនុវត្ត ✓','Apply failed — please try again.'=>'ការអនុវត្តបរាជ័យ — សូមព្យាយាមម្តងទៀត។','Apply to all language versions'=>'អនុវត្តទៅកំណែភាសាទាំងអស់','Apply to Block'=>'អនុវត្តទៅកាន់ផ្ទាំង','Apply to Editor'=>'អនុវត្តទៅកែប្រែ','Apply to Footnote'=>'ដាក់ពាក្យសុំទៅកាន់ Footnote','Apply to Meta Description'=>'ដាក់ពាក្យស្នើសុំទៅកាន់ការពិពណ៌នាផ្នែកមេ','Apply translation'=>'អនុវត្តការបកប្រែ','Applying…'=>'កំពុងអនុវត្ត…','Approximate size'=>'ទំហំប្រហែល','Archive'=>'សៀវភៅប្រចាំ','Archive: %s'=>'សៀវភៅប្រចាំ: %s','Article / WebPage'=>'អត្ថបទ / ទំព័រ Web','Article / WebPage — all singular posts and pages'=>'អត្ថបទ / ទំព័រ Web — សម្រាប់អត្ថបទ និងទំព័រទាំងអស់','Attribute label displayed in this language. Leave empty to use the default label.'=>'ស្លាកសម្គាល់អត្តចរិតដែលបង្ហាញក្នុងភាសានេះ។ ទុកវាឲ្យទទេដើម្បីប្រើស្លាកសម្គាល់លំនាំដើម។','Authors and above (edit_published_posts)'=>'អ្នកនិពន្ធ និងលើស (កែសម្រួលអត្ថបទផ្សាយ)','Auto (recommended)'=>'ស្វ័យប្រវត្តិ (ផ្តល់អនុសាសន៍)','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'ការរកឃើញស្វ័យប្រវត្តិផ្ដល់ឱ្យ: ផលិតផល WooCommerce → ប្រវត្តិផលិតផល; ទំព័រមុខស្ថេរភាព → ប្រវត្តិ Landing; អ្វីផ្សេងទៀត → ប្រវត្តិ Blog។ ជ្រើសប្រវត្តិជាក់លាក់ដើម្បីលើកលែងការនេះសម្រាប់ប្លុកទាំងអស់។','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'បានស្វែងរកស្វ័យប្រវត្តិសម្រាប់ទំព័រមុខស្ថានភាព; អាចជ្រើសរើសដោយដៃ។ ចំណងជើង 20 ពិន្ទុ · ការពិពណ៌នាផ្សាយ 30 ពិន្ទុ · ចំនួនពាក្យ 15 ពិន្ទុ · ចំណងជើង 10 ពិន្ទុ · រូបភាព 15 ពិន្ទុ · តំណភ្ជាប់ 0 ពិន្ទុ។ កំណត់សមត្ថភាព SERP ចំណងជើង 70 តួអក្សរ; ការព្រមានចំនួនពាក្យក្រោម 150, បរាជ័យក្រោម 60; H2 និងតំណភ្ជាប់ក្នុងសំណុំជាជម្រើស។','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'បានស្វែងរកស្វ័យប្រវត្តិសម្រាប់ផលិតផល WooCommerce។ ចំណងជើង 20 ពិន្ទុ · ការពិពណ៌នាផ្សាយ 30 ពិន្ទុ · ចំនួនពាក្យ 15 ពិន្ទុ · ចំណងជើង 5 ពិន្ទុ · រូបភាព 20 ពិន្ទុ · តំណភ្ជាប់ 0 ពិន្ទុ។ កំណត់សមត្ថភាព SERP ចំណងជើង 70 តួអក្សរ; ការព្រមានចំនួនពាក្យក្រោម 80, បរាជ័យក្រោម 40; H2 និងតំណភ្ជាប់ក្នុងសំណុំជាជម្រើស។','Available models reference'=>'យោងម៉ូដែលដែលអាចប្រើបាន','avg'=>'មធ្យម','Batch Analysis'=>'វិភាគជាក្រុម','Behavior'=>'អាកប្បកិរិយា','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'អាកប្បកិរិយា: ជ្រើស preset AI (Literal, Balanced, Creative), បន្ថែមការណែនាំផ្ទាល់ខ្លួនសម្រាប់គេហទំព័រ, បើកឬបិទការប្រែសម្រួលអត្ថបទដោយស្វ័យប្រវត្តិ, និងកំណត់ប្រព័ន្ធចងចាំការប្រែសម្រួល។','Block Content'=>'មាតិកាខ្សែ','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'បង្ហាញការជូនដំណឹងសម្តែងសម្រួលយ៉ាងសមរម្យនៅពេលទំព័របច្ចុប្បន្នត្រូវបានបង្ហាញក្នុងភាសាដើមរបស់វា ពីព្រោះមិនមានការប្រែសម្រួលសម្រាប់ភាសារបស់អ្នកទេសចរ។','Block Editor'=>'កែសម្រួល Block','block keywordfallback'=>'ការបោះបង់','block keywordi18n'=>'i18n','block keywordlanguage'=>'ភាសា','block keywordlinguaforge'=>'Linguaforge','block keywordtranslation'=>'ការប្រែសម្រួល','Block locking'=>'ការចាក់សោ Block','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'គំរូដែលបានចុះបញ្ជីសម្រាប់ប្រភេទ post ផ្ទាល់ខ្លួន។ ប្រើប៊ូតុងបកប្រែដើម្បីផលិតជាវ៉ារីយ៉ង់ភាសា។ មាតិកាប្រែសម្រួលត្រូវបានរក្សាទុកនៅទីនេះ ហើយអាចចម្លងទៅក្នុង post CPT ណាមួយពីកម្មវិធីបញ្ចូលគំរូប្លុក ឬប្រើជាចំណាប់អារម្មណ៍ដើមសម្រាប់គំរូសមកាល (Reusable Block)។','block titleMissing Translation Notice'=>'ការជូនដំណឹងអំពីការប្រែសម្រួលខ្វះ','Block translation reuses'=>'ការប្រើប្រាស់ការប្រែសម្រួលតំបន់','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'កំណត់ត្រាកំណត់ត្រាប្រែសម្រួលនៅលើប្លុក។ នៅពេលដែលបើក, ប្លុកដូចគ្នា (markup ដូចគ្នា, គូភាសា, និងវចនានុក្រម) ត្រូវបានផ្ដល់ពីចង្រ្កានីមួយៗជំនួសការហៅ AI ម្តងទៀត។ ការកែសម្រួលវចនានុក្រម និងការផ្លាស់ប្តូររៀបចំសមាជិកស្វ័យប្រវត្តិចាប់ផ្តើមការបំលែងដែលមានផលប៉ះពាល់។','Blog / Editorial'=>'ប្លុក / ការបោះពុម្ព','Blog / Editorial (default)'=>'ប្លុក / ការបោះពុម្ព (លំនាំដើម)','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'អត្ថបទប្លុកប្រើ Article; ប្រភេទអត្ថបទផ្សេងទៀត និងទំព័រប្រើ WebPage។ រួមមានចំណងជើង, ការពិពណ៌នា, inLanguage, url, datePublished, dateModified, រូបភាព, និងអ្នកបោះពុម្ព។','Browser language redirect'=>'ការបញ្ជូនទៅភាសាដោយកម្មវិធីរុករក','Built-in preset instructions:'=>'ការណែនាំលំនាំមុនដែលមានស្រាប់៖','Bulletize (•-prefixed)'=>'បញ្ជីចុច (•-ដំបូន្មាន)','cached'=>'បានរក្សាទុកជាមុន','Cached API responses'=>'ចម្លើយ API ដែលបានផ្ទុកជាសមាជិក','Cached block translations'=>'ការប្រែសម្រួលប្លុកដែលបានផ្ទុកជាសមាជិក','Cancel'=>'បោះបង់','Cannot determine target language from slug.'=>'មិនអាចកំណត់ភាសាគោលពី slug បាន។','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'មិនអាចសរសេរទៅក្នុងផលិតផល %1$d: វាជាកំណែបកប្រែ (ភាសា: %2$s)%3$s។ ទិន្នន័យប្រតិបត្តិការ (តម្លៃ, ស្តុក, SKU, មាត្រដ្ឋាន) ត្រូវបានធ្វើបច្ចុប្បន្នភាពនៅលើផលិតផលប្រភព។ ដោះសោផលិតផលប្រភពតាមរយៈ: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'ស្លាក canonical','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'កំណត់ការប្រើប្រាស់ AI ដែលអាចបង្កើតបាន និងកំណត់តួនាទីអ្នកប្រើប្រាស់ដែលអាចចាប់ផ្តើមការហៅ AI ដែលបានបង់ប្រាក់។ វាអង្គុយលើកំណត់អត្រាប្រើប្រាស់ប្រើប្រាស់ក្នុងមួយអ្នកប្រើប្រាស់ (30 សំណើរ / នាទី, ត្រូវបានកំណត់ជាខ្លាំង) ដែលបានការពារការរត់លើកមួយរបស់អ្នកប្រើប្រាស់តែម្នាក់ឯង។','Cart'=>'កាត','chars'=>'តួអក្សរ','Check your account, billing, or remaining credits directly on the provider console:'=>'ពិនិត្យមើលគណនីរបស់អ្នក, ការបង់ប្រាក់, ឬសមាជិកនៅផ្ទាល់លើកុងសូលអ្នកផ្គត់ផ្គង់៖','Checkout'=>'ការទូទាត់','Chunk translated'=>'បានបកប្រែឃ្លា','Chunk translated to:'=>'បានបកប្រែឃ្លា៖','Clear'=>'លុបចោល','Clear All'=>'លុបចោលទាំងអស់','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'សម្អាតលទ្ធផល AI ដែលបានរក្សាទុកទាំងអស់? សំណើរពេលអនាគតនឹងបង្កើតការហៅ API ថ្មីរហូតដល់ cache ត្រូវបានសាងសង់ឡើងវិញ។','Clear API Response Cache'=>'សម្អាត Cache ចម្លើយ API','Clear Debug Files'=>'សម្អាតឯកសារចុះហត្ថលេខា','Clear hints'=>'លុបចោលការណែនាំ','Clear input'=>'លុបចោលការបញ្ចូល','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'សម្អាតអង្គចងចាំការបកប្រែទាំងមូល? ការបកប្រែអនាគតនឹងសាងសង់ cache ម្តងទៀតពេលរត់។','Clear Translation Memory'=>'សម្អាតអង្គចងចាំការបកប្រែ','Close'=>'បិទ','Close language panel'=>'បិទផ្ទាំងភាសា','Close popover'=>'បិទ popover','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'ការបង្ហាញចុះចូលរបស់ទិន្នន័យ LF ទាំងអស់នៅក្នុង $wp_rewrite->extra_rules_top។ មានប្រយោជន៍សម្រាប់វិភាគ 404 ឬការប្រឈមមុខនឹងការរុករកក្រោយការបន្ថែមភាសាថ្មី។','Compatibility'=>'ការរួមបញ្ចូលគ្នា','Compliance Preset'=>'ការរៀបចំតាមស្តង់ដារ','Configuration issue: WP site language is not a content language'=>'បញ្ហាកំណត់រចនាសម្ព័ន្ធ: ភាសាគេហទំព័រ WP មិនមែនជាភាសាអត្ថបទទេ។','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'កំណត់អ្នកផ្គត់ផ្គង់ AI នៅក្នុង Settings → API Keys ដើម្បីបើកការណែនាំដោយ AI។','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'កំណត់រចនាសម្ព័ន្ធ hreflang, Open Graph, Schema.org, ផែនទីតំបន់, និងការចែករំលែកសង្គមសម្រាប់រាល់ភាសានៅលើគេហទំព័ររបស់អ្នក។ ផ្នែកនីមួយៗខាងក្រោមគ្រប់គ្រងមុខងារមួយនៃ SEO ភាសាច្រើន។','Configured'=>'បានកំណត់រួចហើយ','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'បញ្ជាក់ថា រចនាសម្ព័ន្ធ permalink សមត្ថភាពសម្របសម្រួលជាមួយផ្លូវ Lingua Forge។ រចនាសម្ព័ន្ធសាមញ្ញ និងលេខតែប៉ុណ្ណោះមិនគាំទ្រ។','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'ទម្រង់ទំនាក់ទំនង 7 (wpcf7_contact_form), ទំនាក់ទំនង Flamingo និងសារចូលមក (flamingo_contact, flamingo_inbound), និងការរួមសម្រួលផ្ទុកសមាជិកភាសា WordPress (wp_sync_storage) ត្រូវបានលែងចូលដោយស្វ័យប្រវត្តិ។ បន្ថែមប្រភេទប្រកាសទីបីផ្សេងទៀតដែលមិនគួរត្រូវបានត្រង់ភាសា, មួយក្នុងមួយបន្ទាត់ឬចែកដោយសញ្ញាក្បៀស។','Content generated'=>'មាតិកាបានបង្កើត','Content Generator'=>'អ្នកបង្កើតមាតិកា','Content profiles and weights'=>'ប្រវត្តិមាតិកា និងទំងន់','Content ready'=>'មាតិកា​រៀបចំរួច','Contributors and above — default (edit_posts)'=>'អ្នកចូលរួម និងលើស — លំនាំដើម (កែសម្រួលអត្ថបទ)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'គ្រប់គ្រងចំនួនមាតិកាដែលផ្ញើទៅ AI និងទំហំចម្លើយដែលអាចមាន។ ទុកវាលទទេដើម្បីប្រើការកំណត់លំនាំដើម (បង្ហាញជាឧទាហរណ៍)។ បង្កើនតម្លៃទាំងនេះ ប្រសិនបើទំព័រធំត្រូវបានកាត់ខ្លះ; បន្ថយវាដើម្បីកាត់បន្ថយការចំណាយ API។','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'គ្រប់គ្រងថវិកាតួអក្សរ និងកំណត់ប្រើសម្រាប់លក្ខណៈពិសេសអ្នកបង្កើតមាតិកា AI។ ទុកវាលទទេដើម្បីប្រើលំនាំដើមដែលមានក្នុងសំណុំបែបបទ។','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'គ្រប់គ្រងអ្វីដែលកើតឡើងនៅពេលអ្នកគ្រប់គ្រងលុបកម្មវិធីពី Plugins → Installed Plugins → Delete។ ការកំណត់កម្មវិធី និង cache AI តែងតែត្រូវបានលុប។ ការចាត់តាំងភាសា និងទំនាក់ទំនងការបកប្រែត្រូវបានរក្សាទុកដោយលំនាំដើម ដូច្នេះការដំឡើងវិញឬការចុះចូលម្តងទៀតអាចបន្តពីកន្លែងដែលបានចាកចេញ។','Conversational'=>'ការសន្ទនា','Copied ✓'=>'បានចម្លង ✓','Copied!'=>'បានចម្លង!','Copy'=>'ចម្លង','Copy and paste into a GitHub issue or support request.'=>'ចម្លង និងភ្ជាប់ទៅក្នុងបញ្ហា GitHub ឬសំណើគាំទ្រ។','Copy failed — please copy the URL manually.'=>'ការចម្លងបរាជ័យ — សូមចម្លង URL ដោយដៃ។','Copy markup'=>'ចម្លង markup','Copy system info'=>'ចម្លងព័ត៌មានប្រព័ន្ធ','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'ចម្លង URL បច្ចុប្បន្នទៅក្នុង Clipboard។ បង្ហាញ toast "Link copied" នៅពេលជោគជ័យ។','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'ចម្លងលទ្ធផលហើយបិទភ្ជាប់វាទៅកន្លែងដែលចាំបាច់ (ឧ. ដោយផ្ទាល់ទៅក្នុងវាលសម្គាល់។)','Copy to safe storage'=>'ចម្លងទៅសុវត្ថិភាព','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'សកម្មភាព JS copy/native/auto: ដំណើរការដោយ LF\'s social-share.js','Could not add entry: source term and target term are required.'=>'មិនអាចបន្ថែមពាក្យស្លាកបាន: តម្រូវឲ្យមានពាក្យប្រភព និងពាក្យគោល។','Could not copy the file. Check that the uploads folder is writable.'=>'មិនអាចចម្លងឯកសារ។ ពិនិត្យមើលថាតើថតផ្ទុកឯកសារអាចសរសេរបានឬអត់។','Could not instantiate the provider.'=>'មិនអាចបង្កើតអ្នកផ្គត់ផ្គង់បាន។','Could not save the file. Check that the uploads folder is writable.'=>'មិនអាចរក្សាទុកឯកសារ។ ពិនិត្យមើលថាតើថត uploads អាចសរសេរបានឬអត់។','Could not save the glossary entry.'=>'មិនអាចរក្សាទុកចុះបញ្ជីវចនានុក្រមបានទេ។','Could not write to robots.txt. Check file permissions.'=>'មិនអាចសរសេរទៅក្នុង robots.txt។ ពិនិត្យការអនុញ្ញាតឯកសារ។','CPT Block Patterns'=>'គំរូប្លុក CPT','Create'=>'បង្កើត','Create missing'=>'បង្កើតអ្វីដែលខ្វះ','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'ការបង្កើតការបកប្រែសម្រាប់ប្រភេទប្រការ "%s" ត្រូវការតំណភ្ជាប់សកម្ម។ សូមធានាថាការតំណភ្ជាប់ដែលត្រូវការត្រូវបានដំឡើង និងសកម្ម។','Creating…'=>'កំពុងបង្កើត…','Creative / Marketing'=>'ច្នៃប្រឌិត / ផ្សព្វផ្សាយ','Creative / Marketing instructions'=>'ការណែនាំច្នៃប្រឌិត / ផ្សព្វផ្សាយ','Current content (will be overwritten)'=>'មាតិកាបច្ចុប្បន្ន (នឹងត្រូវបម្លែង)','Current status'=>'ស្ថានភាពបច្ចុប្បន្ន','Current title'=>'ចំណងជើងបច្ចុប្បន្ន','Current: {current}'=>'បច្ចុប្បន្ន: {current}','Currently emitting'=>'កំពុងបញ្ចេញសំឡេង','Currently inherited from the %s constant. Selecting a value here will override it.'=>'បច្ចុប្បន្នទទួលមរណភាពពីអថេរ %s។ ការជ្រើសតម្លៃនៅទីនេះនឹងលើសសិទ្ធិ។','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'បច្ចុប្បន្នមិនបានប្រើសម្រាប់ប្រកាសដែលប្រើសម្បត្តិ placeholder ប្លុក-មតិ (wp:details summary fields, ល។) — ពួកវាចុះចូលទៅក្នុងផ្លូវការប្រែសម្រួលតែមួយ។','Currently:'=>'បច្ចុប្បន្ន៖','Custom'=>'ផ្ទាល់ខ្លួន','Custom tables — LF post-meta filters do not affect orders.'=>'តារាងផ្ទាល់ខ្លួន — តម្រង LF post-meta មិនមានឥទ្ធិពលលើការបញ្ជាទិញទេ។','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'កំណត់ត្រាអាយអាយប្រចាំថ្ងៃបានសម្រេច (%1$d សំណើរ)។ វាអាចកំណត់ឡើងវិញនៅ %2$s UTC។','Daily quota'=>'កម្រិតប្រចាំថ្ងៃ','Daily request limit'=>'កំណត់សំណើរ​ប្រចាំថ្ងៃ','Danger Zone'=>'តំបន់គ្រោះថ្នាក់','Debug Files'=>'ឯកសារសាកល្បង','Debug files cleared. %d file was removed.'=>'ឯកសារសាកល្បងត្រូវបានសម្អាត។ %d ឯកសារត្រូវបានយកចេញ។' . "\0" . '','Debug Info'=>'ព័ត៌មាន Debug','Debug logging'=>'ការចុះហត្ថលេខាការត្រួតពិនិត្យ','Debug logging disabled.'=>'ការចុះហត្ថលេខាការត្រួតពិនិត្យកំណត់ហេតុបិទ។','Debug logging enabled.'=>'ការចាប់ផ្តើមកំណត់តាមដំណាក់កាលត្រូវបានបើក។','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: បើកកំណត់ហេតុ debug ដើម្បីចាប់យកចម្លើយ AI និងចម្លើយ API ទៅឯកសារមូលដ្ឋាន។ បិទក្រោយពេលសម្រួល — របៀប debug សរសេរឯកសារនៅលើរាល់សំណើ AI។','Default OG image'=>'រូបភាព OG ដំណើរការជាមុន','Default profile'=>'ប្រវត្តិដើម','Delete'=>'លុបចោល','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'លុបឯកសារ .txt ទាំងអស់ក្នុងថត debug? ថតឯកសារនឹងនៅតែម្តង ដើម្បីឲ្យការចុះហត្ថលេខាអនាគតបន្ថែមឲ្យបានសម្រួល។','Delete all files for this override (both .mo and .po)?'=>'លុបឯកសារទាំងអស់សម្រាប់ការប្តូរនេះ (ទាំង .mo និង .po)?','Delete content data on uninstall'=>'លុបទិន្នន័យមាតិកា នៅពេលលុបកម្មវិធី','Delete this glossary entry?'=>'តើចុះបញ្ជីវចនានុក្រមនេះត្រូវការលុបចោលទេ?','Describe what to write — topic, key points, structure…'=>'ពិពណ៌នាអំពីអ្វីដែលត្រូវសរសេរ — ប្រធានបទ ចំណុចសំខាន់ៗ រចនាសម្ព័ន្ធ…','Destructive action — read before proceeding'=>'សកម្មភាពបំផ្លាញ — អានមុនពេលបន្ត។','Details ↗'=>'ព័ត៌មានលម្អិត ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'ស្វែងរកកម្មវិធី SEO សកម្ម (Yoast, Rank Math, ល។) នៅពេលដំណើរការ។ បញ្ចេញតែ og:locale + og:locale:alternate នៅពេលកម្មវិធីផ្សេងទៀតបានបញ្ចេញសំណុំ OG ពេញលេញ; បញ្ចេញសំណុំទាំងមូលនៅពេលមិនមានការរកឃើញ។','Directory'=>'ថតឯកសារ','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'ផ្អាកសម្រាប់តែគេហទំព័រដែលគ្មានផ្ទាំងឬការអនុវត្ត hreflang ផ្ទាល់ខ្លួន។ នៅពេលផ្អាក LF មិនលុបស្លាក canonical មូលដ្ឋានរបស់ WordPress និងមិនបិទការបញ្ចេញ hreflang សម្រាប់ SEO-plugin។','Disabled'=>'ផ្អាក','Disabled (by setting)'=>'ផ្អាក (ដោយការកំណត់)','Disabled (mode setting)'=>'ផ្អាក (ការកំណត់របៀប)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'ផ្អាកដោយសារតែ mu-plugin lf-social-share បានផ្តល់មុខងារនេះរួចហើយ។','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS ត្រូវបានកំណត់។','Display'=>'បង្ហាញ','Displays the Lingua Forge language switcher.'=>'បង្ហាញការប្ដូរភាសា Lingua Forge','Do not output any OG tags.'=>'មិនបញ្ចេញស្លាក OG ទេ។','Documentation'=>'ឯកសារ','Done'=>'រួចរាល់','Done — {done} of {total} post(s) fixed.'=>'បានធ្វើរួចហើយ — បានជួសជុល {done} នៃ {total} អត្ថបទ។','Down'=>'ចុះ','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'ទាញយក និងដំឡើងកញ្ចប់ភាសាមូលដ្ឋាន WordPress តាមផ្លូវផ្ទាល់ពី WordPress.org។ បន្ទាប់ពីដំឡើង, locale នឹងមានស្រាប់សម្រាប់ការរុករក URL និងដំណើរការប្រែសម្រួល AI។ បញ្ជីភាសាដែលអាចប្រើបានត្រូវបានទាញយកតាមតម្រូវការ — ចុចប៊ូតុងខាងក្រោមដើម្បីផ្ទុកវា។','Dropdown direction'=>'ទិសដៅ dropdown','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'មាត្រដ្ឋាននីមួយៗផ្តល់ស្ថានភាពមួយចំនួនបួន: ok (ទំងន់ពេញ), warn (50% នៃទំងន់), fail (0), ឬ info (0, គ្មានការប៉ះពាល់)។ ពិន្ទុ ≥ 80 គឺពណ៌បៃតង, 50–79 ពណ៌សំណុំនៅលើ, តូចជាង 50 ពណ៌ក្រហម។','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'រាល់ប្រសាទត្រូវបានវាយតម្លៃ 0–100 ពីមាត្រដ្ឋានចំនួនប្រាំមួយដែលផ្អែកលើច្បាប់: ចំណងជើង, ការពិពណ៌នាផ្សាយ, ចំនួនពាក្យ, រចនាសម្ព័ន្ធចំណងជើង, ការគ្រប់គ្រងរូបភាព alt, និងតំណភ្ជាប់ក្នុងសំណុំ។ ពិន្ទុដប់ចំនួនតែងតែផ្តល់សម្រាប់ពេលវេលាអាន (ព័ត៌មានតែប៉ុណ្ណោះ)។ 90 ពិន្ទុដែលនៅសល់ចែកចាយទៅលើមាត្រដ្ឋានផ្សេងទៀតដែលមានទំងន់ខុសគ្នាតាមប្រវត្តិមាតិកា (មើលខាងក្រោម)។','edit'=>'កែសម្រួល','Editors and above (edit_others_posts)'=>'អ្នកកែសម្រួល និងលើស (កែសម្រួលអត្ថបទផ្សេងៗ)','Enable API response caching'=>'បើកការរក្សាទុកចម្លើយ API','Enable block-level translation cache reuse across posts'=>'អនុញ្ញាតឲ្យប្រើកម្រងចងចាំការប្រែសម្រួលនៅកម្រិតប្លុកក្នុងប្រកាសផ្សេងៗ','Enable Social Share URL rewriting for Social Icons blocks'=>'បើកការសរសេរវេបសាយសង្គមសម្រាប់ប្លុកស្លាកសង្គម','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'បើកដំណើរការពេលដែលប្រធានបទរបស់អ្នកបង្ហាញជា H2 ជំនួស H1 (ជារឿយៗនៅក្នុងប្រធានបទប្លុកខ្លះ)។ អ្នកវិភាគទាញយកទំព័រដែលបានបង្ហាញ ហើយបើរកមិនឃើញ H1 ប៉ុន្តែមាន H2 អ្នកនឹងលើក H2 ដំបូងទៅជា H1 សម្រាប់គណនាការវាយតម្លៃ។','Environment'=>'បរិស្ថាន','environment variable'=>'អថេរបរិស្ថាន','Error'=>'កំហុស','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'រាល់ពេលដែលមានការវិភាគប្រសាទ ពិន្ទុត្រូវបានរក្សាទុកក្នុងមេតា​ប្រសាទ។ ជួរឈរភាសារបស់បញ្ជីប្រសាទបង្ហាញសញ្ញាប័ណ្ណ "SEO N" មានពណ៌សម្រាប់ប្រសាទណាមួយដែលបានវិភាគយ៉ាងហោចណាស់មួយដង។ ពេលដែលមានពិន្ទុពីរត្រូវបានរក្សាទុក សញ្ញាស្លាក delta (↑N / ↓N) បង្ហាញការផ្លាស់ប្តូរពីការរត់មុន។','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'ត្រូវការតែមួយ H1 ប៉ុណ្ណោះ។ H1 ជាទូទៅគឺជា​ចំណងជើងប្រសាទដែលបានបង្ហាញដោយប្រធានបទ — វាត្រូវបានអានពីទំព័រដែលបានបង្ហាញនៅក្នុងសកម្មភាពពេលមានសក្តានុពល, ហើយពីមាតិកាប្រសាទជាជម្រើសបន្ថែម។','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'ឧទាហរណ៍នៃការកំណត់រចនាសម្ព័ន្ធដែលគាំទ្រ: ភាសាគេហទំព័រ WP = CA (Catalan), ភាសាអត្ថបទ = CA + ES។','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'ឧទាហរណ៍នៃការកំណត់រចនាសម្ព័ន្ធមិនគាំទ្រ: ភាសាគេហទំព័រ WP = EN (English), ភាសាអត្ថបទ = CA + ES តែប៉ុណ្ណោះ។ ភាសាអង់គ្លេសមិនមែនជាភាសាអត្ថបទទេ, ដូច្នេះ Lingua Forge មិនអាចផ្គូផ្គងភាសា WP ជាមួយក្រុមបកប្រែណាមួយទេ។','Exclude from navigation menus'=>'កាត់ចេញពីម៉ឺនុយនាវីហ្គេសិន','Exclude from routing'=>'ដកចេញពីការរុករក','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'ដកប្រភេទប្រសាទនេះចេញពីការរុករកភាសា — ប្រសាទរបស់វានឹងមិនបង្ហាញនៅទីនេះឬទទួល _lf_lang ទេ។ នេះមិនអាចត្រូវបានធ្វើឲ្យស្វ័យប្រវត្តិវិញបាន។','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'ដកប្រភេទប្រសាទនេះចេញពីការរុករកភាសា? ប្រសាទរបស់វានឹងមិនបង្ហាញនៅក្នុងបញ្ជីនេះឬទទួល _lf_lang។ អ្នកអាចផ្លាស់ប្តូរវានៅក្នុងការកំណត់ → Router → ការលើកលែងសំណួរ។','excluded from routing'=>'បានដកចេញពីការរុករក','Excluded post types'=>'ប្រភេទប្រសាទដែលបានដកចេញ','Excluding…'=>'កំពុងដកចេញ…','Expand'=>'ពង្រីក','Expected: {expected}'=>'ចាំបាច់: {expected}','External share services'=>'សេវាកម្មចែករំលែកក្រៅប្រព័ន្ធ','Extra guidance — tone, style, constraints, target audience…'=>'ការណែនាំបន្ថែម — សម្លេង, ស្តាយ, កំណត់, អ្នកទស្សនាគោល…','Extra guidance — tone, style, constraints…'=>'ការណែនាំបន្ថែម — សម្លេង, ស្តាយ, កំណត់…','Failed to save exclusion.'=>'បរាជ័យក្នុងការរក្សាទុកការលើកលែង។','Failed. Please try again.'=>'បរាជ័យ។ សូមព្យាយាមម្តងទៀត។','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL រូបភាព fallback ប្រើនៅពេលទំព័រមិនមានរូបភាពពិសេស ឬស្លាកសញ្ញា។ បង្ហាញនៅក្នុងការពិនិត្យសង្គមសម្រាប់អាក្រក់, សន្ទស្សន៍ប្លុក, និងទំព័រពិសេសណាមួយដែលមិនមាន thumbnail។','Feature'=>'លក្ខណៈពិសេស','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'មុខងារត្រូវបានក្រុមហ៊ុនចូលរួមចំណែកចូលក្នុងពីរប្រភេទ។ បញ្ចូលអត្តសញ្ញាណម៉ូដែលត្រឹមត្រូវសម្រាប់រាល់ប្រភេទ និងអ្នកផ្គត់ផ្គង់។ ទុកវាលទទេដើម្បីប្រើលំនាំដើម។','File copied to safe storage successfully.'=>'ឯកសារត្រូវបានចម្លងទៅសុវត្ថិភាពដោយជោគជ័យ។','File modifications are disabled (DISALLOW_FILE_MODS).'=>'ការកែសម្រួលឯកសារត្រូវបានផ្អាក (DISALLOW_FILE_MODS)។','Files'=>'ឯកសារ','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'ឯកសារនៅក្នុងថតខាងក្រោម។ មានប្រយោជន៍សម្រាប់សម្រួលបញ្ហាផ្លាស់ប្តូរវិចារណា — បិទវាពេលដែលអ្នកមានអ្វីដែលត្រូវការ ដើម្បីឲ្យឯកសារមិនបន្ថែម។ អ្នកអាចបង្ខាំងវាពី wp-config.php ជាមួយ `define( \'LINGUAFORGE_AI_DEBUG\', true );` ដែលជាអ្នកបដិសេធការបិទបើក។','Filter'=>'តម្រង','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'តម្រងដោយភាសា និងប្រភេទអត្ថបទ, បើកមើលមាតិការបស់អ្នក, ហើយចុចវិភាគលើធាតុណាមួយដើម្បីអនុវត្តការត្រួតពិនិត្យ SEO ដោយផ្អែកលើច្បាប់ — ប្រវែងចំណងជើង, ការពិពណ៌នាផ្សាយ, ចំនួនពាក្យ, រចនាសម្ព័ន្ធចំណងជើង, ការគ្រប់គ្រងរូបភាព alt, និងតំណភ្ជាប់ក្នុង។','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'តម្រង់ជាមួយ linguaforge_debug_dir ដើម្បីបញ្ជូនចេញ debug ទៅទីតាំងមិនសាធារណៈ។','Finding'=>'ការរកឃើញ','Fix'=>'ជួសជុល','Fix All'=>'ជួសជុលទាំងអស់','Fix all links'=>'ជួសជុលតំណភ្ជាប់ទាំងអស់','Fix all parts'=>'ជួសជុលផ្នែកទាំងអស់','Fix Links'=>'ជួសជុលតំណភ្ជាប់','Fix Nav'=>'ជួសជុលការរុករក','Fix Parts'=>'ជួសជុលផ្នែក','Fix Template'=>'ជួសជុល Templates','Fix: go to'=>'ជួសជុល: ទៅកាន់','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'ជួសជុល namespace អ្នកកែសម្រួលតំបន់បណ្តាញ និងស្លាក _lf_lang នៅលើគំរូ FSE ដែលបានសម្រួលដោយ LF ទាំងអស់ដែលរកឃើញក្នុងមូលដ្ឋានទិន្នន័យ។ ប្រើវាក្រោយពេលធ្វើបច្ចុប្បន្នភាពពីកំណែចាស់របស់ Lingua Forge — វាប្តូរទំរង់ WooCommerce ពីក្រុមប្រធានបទសកម្មទៅក្រុម WooCommerce នៅក្នុងអ្នកកែសម្រួលតំបន់បណ្តាញ ហើយធានាថាគំរូទាំងអស់អាចរកឃើញបានដោយរបាយការណ៍ការអភិវឌ្ឍន៍។','Fixing {n} / {total}…'=>'កំពុងជួសជុល {n} / {total}…','Fixing…'=>'កំពុងជួសជុល…','Flush Permalink Rules'=>'បិទបញ្ជីច្បាប់ Permalink','Flush Permalinks'=>'បិទបញ្ជី Permalinks','Flush Sitemap Cache'=>'បញ្ចូល Cache Sitemap','Footnote Content'=>'មាតិកាសម្គាល់','footnote(s) translated — applied together with content.'=>'បានបកប្រែសម្គាល់(ៗ) — បានអនុវត្តជាមួយមាតិកា។','Footnotes'=>'សម្គាល់','Footnotes payload (advanced)'=>'Payload សម្គាល់ចំណុចសម្គាល់ (កម្រិតខ្ពស់)','Forbidden'=>'ហាមឃាត់','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'បិទដោយស្ថានភាព LINGUAFORGE_AI_DEBUG នៅក្នុង wp-config.php។ ដកបន្ទាត់នោះចេញដើម្បីគ្រប់គ្រងការបិទបើកនេះពីទីនេះ។','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'បង្ខាំងដោយស្ថានភាព LINGUAFORGE_AI_DEBUG នៅក្នុង wp-config.php។ ដកបន្ទាត់នោះចេញដើម្បីគ្រប់គ្រងការបិទបើកនេះពីទីនេះ។','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'បង្ខំឲ្យសំណើក្រោយបង្អស់បង្កើតសitemap ម្តងទៀត។ ប្រើក្រោយការនាំចូលទិន្នន័យច្រើន ឬកែសម្រួលដោយដៃទំនាក់ទំនងបកប្រែ។','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'មានកំហុសឬអាកប្បកិរិយាភ្ញាក់ផ្អើល? សូមបើកបញ្ហានៅលើ GitHub — រួមបញ្ចូលព័ត៌មាន Debug ខាងលើ និងការពិពណ៌នាសង្ខេបអំពីអ្វីដែលអ្នករំពឹងទុកនិងអ្វីដែលកើតឡើង។','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'រកឃើញ {parts} នៅក្នុង <strong>{total}</strong> នៃ <strong>{scanned}</strong> អត្ថបទដែលបានស្កេនសម្រាប់ <strong>{lang}</strong>។','From'=>'ពី','Front Page'=>'ទំព័រមុខ','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'ការចងសមាជិក FSE: ស្ពាន់, ប្រែសម្រួល, និងជួសជុលតំណភ្ជាប់នៅក្នុងគំរូ និងផ្នែកគំរូទាំងមូលពីផ្ទាំងនេះ។','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'គំរូ FSE ដែលបានចាប់ផ្តើមពីប្រធានបទសកម្ម។ បង្កើតហើយកែសម្រួលនៅក្នុងអ្នកកែសម្រួលតំបន់បណ្តាញ។','Full'=>'ពេញ','Full Article'=>'អត្ថបទពេញ','Full post'=>'អត្ថបទពេញ','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'ការប្រែសម្រួលទំព័រពេញ, អ្នកបង្កើតមាតិកា (ម៉ូដែលកម្រិតមធ្យមគឺគ្រប់គ្រាន់)','General'=>'ទូទៅ','Generate'=>'បង្កើត','Generate Content'=>'បង្កើតមាតិកា','Generate content…'=>'បង្កើតមាតិកា…','Generate Excerpt'=>'បង្កើតចំណងជើងខ្លី','Generate Meta Description'=>'បង្កើតការពិពណ៌នាអំពីមេតា','Generate the multilingual sitemap at /lf-sitemap.xml'=>'បង្កើត sitemap ភាសាច្រើននៅ /lf-sitemap.xml','Generated Content'=>'មាតិកាដែលបានបង្កើត','Generated meta description'=>'ការពិពណ៌នាមេតាដែលបានបង្កើត','Generating…'=>'កំពុងបង្កើត…','Generation failed.'=>'ការបង្កើតបរាជ័យ។','Getting started'=>'ចាប់ផ្តើម','Global AI preset'=>'ការរៀបចំ AI សកល','Global default (%s)'=>'លំនាំដើមសកល (%s)','Glossary'=>'ពាក្យស្លាក','Glossary entry added.'=>'បញ្ចូលពាក្យស្លាកបានបន្ថែម។','Glossary entry removed.'=>'លុបចោលពាក្យស្លាក។','Glossary Tab'=>'ផ្ទាំងពាក្យសព្ទ','Google (Gemini)'=>'Google (Gemini)','Google AI Studio'=>'ស្ថានីយ៍ Google AI','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'ម៉ូដ H2 ជា H1 បានបើក — ចំណងជើងត្រូវបានគណនាជាសមាជិក H1។ (ស្លាកចំណងជើងមិនអាចរកឃើញពីទំព័រដែលបានបង្ហាញ; សូមផ្ទៀងផ្ទាត់ថាប្រធានបទរបស់អ្នកបញ្ចេញចំណងជើងត្រឹមត្រូវ។)','Heading structure rules'=>'ច្បាប់រចនាសម្ព័ន្ធចំណងជើង','Headings'=>'ចំណងជើង','Hide'=>'លាក់','High-Performance Order Storage (HPOS)'=>'ការរក្សាទុកតម្រៀបប្រសិទ្ធភាពខ្ពស់ (HPOS)','Hints'=>'គន្លឹះ','Home link text'=>'អត្ថបទតំណទៅផ្ទះ','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'របៀបដែលវាគួរត្រូវបានបង្ហាញក្នុងការប្រែប្រែ។ ប្រើតម្លៃដូចគ្នាជាពាក្យប្រភពដើម្បីណែនាំឲ្យ AI រក្សាទុកវាឲ្យបានតាមពិត។','How to use'=>'វិធីប្រើ','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT ត្រូវបានសមកាល; តម្រង LF post-meta អនុវត្តទៅលើចម្លង CPT។','Hreflang'=>'Hreflang','Hreflang output'=>'ការបញ្ចេញ hreflang','Hreflang settings saved.'=>'ការកំណត់ hreflang បានរក្សាទុក។','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'រូបតំណាង + ស្លាក','Icon only'=>'តែរូបតំណាង','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'បើបានធ្វើការ​ជ្រើសរើស វិធីសាស្ត្រនេះនឹងលុបចោលការចាត់តាំងភាសា, ទំនាក់ទំនងការបកប្រែ, ការពិពណ៌នាមេតា, ការកំណត់ជាសមាជិកទំព័រ, វចនានុក្រម AI, និងអង្គចងចាំការបកប្រែសម្រាប់អត្ថបទទាំងអស់នៅលើគេហទំព័រ។ នេះមិនអាចត្រឡប់បានទេ។ មិនត្រូវចុចជ្រើសរើសទេ លុះត្រាអ្នកចង់យកការគាំទ្រភាសចម្រុះចេញពីគេហទំព័រ។','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'បើអ្នកមានផ្លាក SEO ទូទៅដំឡើង, ផ្ទាំងនេះបង្ហាញពីរបៀប LF យល់ដឹងពីការរួមបញ្ចូលដើម្បីចៀសវាងការបញ្ចេញសមាជិកច្រើន។ គោលបំណងគឺការជៀសវាងការប៉ះទង្គិច — មិនមែនសហការណ៍។ LF ផ្តល់ស្រទាប់ SEO ភាសាច្រើន (hreflang, og:locale, inLanguage schema) ដែលត្រូវការចំណេះដឹងពីការរៀបចំផ្លូវភាសារបស់ LF ដើម្បីផលិតបានត្រឹមត្រូវ។','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'បើអ្នកមាន Yoast SEO, Rank Math, All in One SEO, ឬ SEOPress ដំឡើង, Lingua Forge ស្គាល់ពួកវា ហើយសម្របសម្រួលដើម្បីចៀសវាងការបញ្ចេញសមាជិកច្រើន។ សម្រាប់ hreflang, LF យកចាប់ផ្តើមទាំងស្រុង ហើយបិទការបញ្ចេញរបស់ plugin ដោយសារតែ plugin មិនអាចផលិត hreflang ត្រឹមត្រូវសម្រាប់ការរៀបចំផ្លូវភាសាច្រើន។ សម្រាប់ Open Graph, LF បន្ថែមតែ og:locale និង og:locale:alternate — សញ្ញាសហភាសាដែល plugin មិនអាចផ្តល់បាន — ហើយទុកសំណុំ OG មូលដ្ឋានទៅឱ្យ plugin។ សម្រាប់ Schema.org, LF ផ្អាកការបញ្ចេញរបស់ខ្លួនឯងទាំងស្រុងដើម្បីចៀសវាងគំនូស JSON-LD ដែលមានការប្រកួតប្រជែង។','Images'=>'រូបភាព','Improve writing'=>'ធ្វើឱ្យប្រសើរឡើង','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'នៅក្នុងកម្មវិធីកែសម្រួលប្លុក, បន្ថែមប្លុកស្លាកសង្គម។ សម្រាប់រាល់រូបតំណាង, បើកការកំណត់តំណភ្ជាប់ ហើយបញ្ចូលមួយក្នុងចំណោម "share:" តម្លៃខាងក្រោមជាអាសយដ្ឋាន URL។ នៅលើផ្នែកមុខ, LF ជំនួសវាជា URL ចែករំលែកត្រឹមត្រូវសម្រាប់ទំព័របច្ចុប្បន្ន។','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'រួមមានឈ្មោះ, ការពិពណ៌នា, inLanguage, url, រូបភាព, និង Offer ជាមួយតម្លៃ, រូបិយប័ណ្ណ, និងភាពអាចប្រើបាន។ តម្លៃ និងភាពអាចប្រើបានមកពីផលិតផលភាសាមូលដ្ឋាន (ម៉ូដែលស្តុកចែករំលែក)។','Includes site name, url, and inLanguage.'=>'រួមមានឈ្មោះតំបន់, url, និង inLanguage។','Informative'=>'ព័ត៌មាន','Input tokens'=>'Token បញ្ចូល','Install'=>'ដំឡើង','Install a Language'=>'ដំឡើងភាសា','Installed SEO plugins'=>'កម្មវិធី SEO ដែលបានដំឡើង','Installing…'=>'កំពុងដំឡើង…','instock / oos / pending from WC stock status'=>'instock / oos / pending ពីស្ថានភាពស្តុក WC','Instructions (optional)'=>'ការណែនាំ (ជាជម្រើស)','Instructions / key points'=>'ការណែនាំ / ចំណុចសំខាន់ៗ','Insufficient permissions.'=>'សិទ្ធិមិនគ្រប់គ្រាន់។','Integration API'=>'API ការរួមបញ្ចូល','Internal Link Fixer'=>'ជួសជុលតំណភ្ជាប់ក្នុង','Introduction only'=>'តែការណែនាំ','Invalid API key — double-check the key entered in the AI Provider settings.'=>'កូនសោ API មិនត្រឹមត្រូវ — ពិនិត្យមើលកូនសោដែលបានបញ្ចូលក្នុងការកំណត់រចនាសម្ព័ន្ធអ្នកផ្គត់ផ្គង់ AI។','Invalid file reference.'=>'យោងឯកសារមិនត្រឹមត្រូវ។','Invalid filename.'=>'ឈ្មោះឯកសារមិនត្រឹមត្រូវ។','Invalid language code.'=>'កូដភាសាមិនត្រឹមត្រូវ។','Invalid language.'=>'ភាសាមិនត្រឹមត្រូវ។','Invalid locale code.'=>'កូដ locale មិនត្រឹមត្រូវ។','Invalid or primary language.'=>'ភាសាខុសឬមេមិនត្រឹមត្រូវ។','Invalid post ID.'=>'លេខសម្គាល់អត្ថបទមិនត្រឹមត្រូវ។','Invalid post type.'=>'ប្រភេទអត្ថបទមិនត្រឹមត្រូវ។','Invalid taxonomy.'=>'ប្រភេទទិន្នន័យមិនត្រឹមត្រូវ។','Invalid template part.'=>'ផ្នែកគំរូមិនត្រឹមត្រូវ។','Invalid template type.'=>'ប្រភេទគំរូមិនត្រឹមត្រូវ។','JavaScript-powered actions'=>'សកម្មភាពដែលផ្អែកលើ JavaScript','Just now'=>'ឥឡូវនេះប៉ុណ្ណោះ','Key points, ideas, or structure to build from…'=>'ចំណុចសំខាន់ៗ, គំនិត, ឬរចនាសម្ព័ន្ធដែលត្រូវសាងសង់ពី…','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'កូនសោត្រូវបានសម្ងាត់នៅពេលស្តុកដោយប្រើ AES-256-GCM ជាមួយសម្ងាត់ផ្ទៃតំបន់ (LINGUAFORGE_SECRET)។ កុំចែករំលែកនាំចេញមូលដ្ឋានទិន្នន័យដោយមិនបង្វិលសម្ងាត់ជាមុន។','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'កូនសោ API ត្រូវបានសម្ងាត់ជាមួយ AES-256-CBC មុននឹងផ្ទុកក្នុងមូលដ្ឋានទិន្នន័យ WordPress។ សម្ងាត់ការសម្ងាត់ត្រូវបានបង្កើតពីស្លាកសុវត្ថិភាព WordPress របស់អ្នក (wp-config.php) ដូច្នេះកូនសោ plaintext មិនធ្លាប់ចូលទៅក្នុងមូលដ្ឋានទិន្នន័យ។','Landing / Short-form'=>'Landing / Short-form','Language'=>'ភាសា','Language %s installed successfully.'=>'ភាសា %s ត្រូវបានដំឡើងដោយជោគជ័យ។','Language (optional)'=>'ភាសា (ជាជម្រើស)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'ការដំឡើងភាសាត្រូវបានបិទនៅលើម៉ាស៊ីនបម្រើនេះ (បានកំណត់ DISALLOW_FILE_MODS)។','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'ការដំឡើងភាសាត្រូវបានបិទនៅលើម៉ាស៊ីនបម្រើនេះ។ អថេរ DISALLOW_FILE_MODS ត្រូវបានកំណត់នៅក្នុង wp-config.php។ ដំឡើងកញ្ចប់ភាសាដោយដៃតាមរយៈ WP-CLI: wp language core install de_DE','Language label'=>'ស្លាកភាសា','Language Overrides'=>'ការប្រែសម្រួលភាសា','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'ការបញ្ជូនភាសា: គ្រប់គ្រងឯកសារ .po/.mo ផ្ទាល់ខ្លួនសម្រាប់អក្សររបស់ UI Lingua Forge។ ប្រើវាជំនួសការកែសម្រួលឯកសារផ្លាស់ប្តូរ — ការបញ្ជូនភាសានៅរស់នៅ។','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'ការដំឡើងកញ្ចប់ភាសាបរាជ័យ។ ភាសាអាចមានរួចហើយ, កូដ locale អាចមិនត្រឹមត្រូវ, ឬម៉ាស៊ីនបម្រើរបស់អ្នកអាចបិទការសរសេរឯកសារ។','Language Setup'=>'ការរៀបចំភាសា','Language Switcher'=>'ប្ដូរភាសា','Language switcher'=>'អ្នកផ្លាស់ប្តូភាសា','Language uninstalled. %d post deleted.'=>'ភាសាអត្រាបានលុបចេញ។ %d: ចំនួនអត្ថបទដែលបានលុប' . "\0" . '','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'ចម្លងភាសាដែលមានសម្រាប់ផ្នែកគំរូរបស់ប្រធានបទ។ បន្ទាប់ពីចាប់ផ្តើម, គំរូនឹងត្រូវបានធ្វើឲ្យទាន់សម័យដើម្បីយោងទៅកាន់ផ្នែកភាសាដែលមានសម្រាប់ភាសា។','Language:'=>'ភាសា៖','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'ភាសាដែលស្គាល់ឥឡូវនេះទៅកាន់ router (បានយកពីកញ្ចប់ locale WordPress ដែលបានដំឡើង និងភាសាសំខាន់)។ ដំឡើងកញ្ចប់ភាសាផ្សេងទៀតនៅផ្នែកខាងក្រោមដើម្បីធ្វើឲ្យមានភាសាច្រើនសម្រាប់ការរុករក និងការប្រែសម្រួល។','Last 30 days'=>'30 ថ្ងៃចុងក្រោយ','Last 7 days'=>'7 ថ្ងៃចុងក្រោយ','Last generated: %s'=>'បានបង្កើតចុងក្រោយ: %s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'ពិន្ទុ SEO ដោយផ្អែកលើច្បាប់ចុងក្រោយ។ ប្រើការវិភាគនៅក្នុង ការកំណត់ → SEO → វិភាគ ដើម្បីធ្វើឱ្យទាន់សម័យ។','Last run: %s ago'=>'ការរត់ចុងក្រោយ: %s មុននេះ','Lead paragraph (≤60 w)'=>'អត្ថបទនាំ (≤60 ពាក្យ)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'ទុកវាលម៉ូដែលទទេដើម្បីប្រើម៉ូដែលលំនាំដើមសម្រាប់ស្រទាប់នោះ។ អត្ថបទ placeholder បង្ហាញម៉ូដែលណាដែលនឹងប្រើ។','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'ទុកវាឲ្យទទេសម្រាប់ឈ្មោះម៉ាក និងពាក្យសម្ងាត់ដែលមិនពាក់ព័ន្ធនឹងភាសាណាមួយដែលគួរត្រូវបានអនុវត្តន៍ដោយគ្មានការប្រែប្រែ។','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'ទុកវាឲ្យទទេដើម្បីអនុវត្តចុះបញ្ជីនេះទៅភាសាគោលទាំងអស់ — សម្រាប់ឈ្មោះម៉ាក អក្សរអក្សរ និងពាក្យដែលត្រូវរក្សាទុកតាមពិតក្នុងការប្រែប្រែទាំងអស់។','Leave blank to keep the existing key. Enter a new value to replace it.'=>'ទុកវាឲ្យទទេដើម្បីរក្សាកូនសោចាស់។ បញ្ចូលតម្លៃថ្មីដើម្បីជំនួសវា។','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'ទុកវាលទទេដើម្បីប្រើលំនាំដើម។ ការលុបចោលការកំណត់តម្លៃដែលបានរក្សាទុកនឹងធ្វើឲ្យវាប្រតិបត្តិជាលំនាំដើមនៅពេលបន្ទាប់។','Legacy lf-social-share mu-plugin'=>'mu-plugin lf-social-share បុរាណ','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'បានរកឃើញ mu-plugin lf-social-share បុរាណ។ LF កំពុងផ្ទេរតំណភ្ជាប់ OG មូលដ្ឋានទៅ mu-plugin ហើយបញ្ចេញ og:locale + og:locale:alternate តែប៉ុណ្ណោះ។ អ្នកអាចបិទ mu-plugin — LF មានសមត្ថភាពសង្គមផ្ទៃក្នុង (ផ្ទាំង SEO → ផ្ទាំងសង្គម) និង Open Graph មានមុខងារដូចគ្នា។','Legacy post-based (CPT)'=>'ប្រព័ន្ធចាស់ដែលផ្អែកលើប្រសាទ (CPT)','Legal / Compliance'=>'ច្បាប់ / ការអន្ដរាគមន៍','Legal / Compliance instructions'=>'ការណែនាំផ្នែកច្បាប់ / ការអនុវត្ត','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF តែងតែបន្ថែម og:locale និង og:locale:alternate — សញ្ញាសហភាសាដែលស្លាក SEO មិនអាចផ្តល់បានត្រឹមត្រូវ។ សម្រាប់សំណុំ OG មូលដ្ឋាន (og:title, og:description, og:image), LF បញ្ចេញវាពេលដែលមិនមាន plugin ផ្សេងទៀត។ នៅពេលមាន plugin SEO, LF បោះបង់សំណុំមូលដ្ឋានដើម្បីចៀសវាងស្លាកច្រើន — មិនមែនដោយសារតែ plugin "ល្អ" ទេ, ប៉ុន្តែដោយសារតែការចម្លងមិនមានតម្លៃ។','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF បង្កើត sitemap ផ្ទាល់ខ្លួនដែលមាន xhtml:link ជំនួសសម្រាប់ក្រុមបកប្រែទាំងអស់។ នៅពេលមាន plugin SEO, វាបង្កើត sitemap ផ្សេងទៀត — ទាំងពីររួមគ្នាដោយសេរី។ ផ្ញើសំណុំទាំងពីរទៅ Google Search Console: sitemap របស់ plugin SEO សម្រាប់ការរកឃើញមាតិកា, និង sitemap របស់ LF សម្រាប់សញ្ញាភាសា។','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF កំពុងបញ្ចេញស្លាក hreflang ហើយបានយកចេញស្លាក canonical មូលដ្ឋានរបស់ WordPress នៅលើទំព័រភាសាច្រើន។','LF is suppressing hreflang output from: %s'=>'LF កំពុងបិទការបញ្ចេញ hreflang ពី: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF បញ្ចេញ hreflang ត្រឹមត្រូវសម្រាប់ភាសាទាំងអស់ដែលបានកំណត់រួចរួមទាំង x-default។ ផ្លាក SEO ទូទៅមិនមានចូលដំណើរការការរៀបចំផ្លូវភាសារបស់ LF ហើយអាចបង្កើត hreflang ដោយផ្អែកលើការសន្និដ្ឋាន URL មិនត្រឹមត្រូវ។ LF បិទការបញ្ចេញរបស់ពួកវាតាមតម្រូវការដើម្បីចៀសវាងការប៉ះទង្គិច។','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF បញ្ចេញ JSON-LD ភាសាច្រើនដែលមានការបញ្ជាក់ inLanguage ដែលភ្ជាប់ទៅនឹងការរៀបចំផ្លូវភាសារបស់វា។ នៅពេលមាន plugin SEO, LF ផ្អាក schema របស់ខ្លួនឯងទាំងស្រុង: JSON-LD ដែលមានការប្រកួតប្រជែងបង្កើតកំហុសក្នុងការផ្ទៀងផ្ទាត់ និងមិនមានវិធីសាស្ត្រល្អក្នុងការបន្ថែមស្រាប់។','LF provides'=>'LF ផ្តល់','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF លុបស្លាកសញ្ញាគោលនយោបាយមេដាយ WordPress នៅលើទំព័រភាសាច្រើនដោយសារតែច្បាប់ស្ដារឡើងវិញដែលមានផ្លូវភាសា និង hreflang x-default គឺជាសញ្ញាសម្រង់សម្រង់សម្រង់សម្រង់សម្រាប់គេហទំព័រភាសាច្រើន។ នេះបង្កើតការពារការបង្កើតស្លាកសញ្ញាសម្រង់សម្រង់ពីរដង ប្រសិនបើកម្មវិធី SEO ផងដែរ ផ្តល់ចេញមួយ។ LF មិនបន្ថែមស្លាកសញ្ញាសម្រង់ផ្ទាល់ខ្លួនទេ — ការរុករកផ្លូវភាសានalready makes each URL canonical.','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'ចំណងជើងចុះបញ្ជី LF នៅក្នុង $wp_rewrite->extra_rules_top។ មានប្រយោជន៍សម្រាប់ការរកឃើញ 404 ឬការប្រឈមមុខនឹងការរៀបចំផ្លូវ។ ចម្លងទាំងនេះពេលដាក់របាយការណ៍កំហុស។','Light'=>'ភ្លឺៗ','Light (default — fast and cost-effective)'=>'ភ្លឺ (លំនាំដើម — លឿន និងមានថ្លៃសមរម្យ)','Light (fast and cost-effective — Haiku / Flash)'=>'ភ្លឺ (លឿន និងមានថ្លៃសមរម្យ — Haiku / Flash)','Light model'=>'ម៉ូដែលសLight','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'ភ្លឺ: ប្រើសម្រាប់ការពិពណ៌នាអំពីមេតា និងការបង្កើតសេចក្ដីសង្ខេប — លឿន, តម្លៃទាប។','Limit results to pages in the given Lingua Forge language code.'=>'កំណត់លទ្ធផលទៅទំព័រដែលមានកូដភាសា Lingua Forge ដែលបានផ្ដល់។','Limits'=>'កំណត់','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge បន្ថែមការរុករកភាសពហុភាសា, ការប្រែសម្រួលដោយ AI, ស្លាក hreflang SEO, និងអ្នកផ្លាស់ប្តូភាសាទៅលើគេហទំព័ររបស់អ្នក។','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge បន្ថែមលក្ខណៈពិសេស Open Graph សម្រាប់ WooCommerce ទៅលើទំព័រផលិតផល ដើម្បីឲ្យការចែករំលែក URL ផលិតផលនៅលើ Facebook, Pinterest និងវេទិកាផ្សេងទៀត បង្ហាញប្រភេទផលិតផល តម្លៃ និងភាពអាចប្រើបានត្រឹមត្រូវ។','Lingua Forge AI Tools'=>'ឧបករណ៍ AI Lingua Forge','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge បន្ថែមសមាសភាពសង្គមសម្រាប់ WordPress Core Social Icons ជាមួយ URL ចែករំលែកដែលអាចផ្លាស់ទីបាន។ កំណត់តំណរបស់សញ្ញាណណាមួយទៅតម្លៃ "share:" ហើយ LF ប្ដូរវាទៅជា URL ចែករំលែកត្រឹមត្រូវ ឬសកម្មភាព JavaScript នៅពេលបង្ហាញ — មិនចាំបាច់កូដផ្ទាល់ខ្លួន ឬកម្មវិធីផ្នែកទីបីទេ។','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge បង្កើតផែនទីសាយ XML ផ្តាច់មុខនៅ /lf-sitemap.xml ដែលបន្ថែមតំណភាសាជំនួសសម្រាប់មាតិកាដែលបានបកប្រែរបស់អ្នក។ ផែនទីសាយនេះបន្ថែមសមាជិកផែនទីសាយ WordPress និងផែនទីសាយ SEO ផ្សេងទៀត — វាមិនជំនួសពួកវាទេ។','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge ជាដំណោះស្រាយ SEO ភាសាច្រើនពេញលេញ។ មិនចាំបាច់កម្មវិធី SEO បន្ថែមទេ។','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge ជាដំណោះស្រាយ SEO ភាសាច្រើនពេញលេញ។ មិនចាំបាច់កម្មវិធី SEO ឬផែនទីសាយបន្ថែមទេ។','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge ផ្តល់លទ្ធផល <link rel="alternate" hreflang> សម្រាប់ភាសាទាំងអស់ដែលបានកំណត់នៅលើទំព័ររាល់ទំព័រ រួមទាំង x-default ដែលបង្ហាញទៅកាន់ភាសាមូលដ្ឋាន។ នេះគឺជាសញ្ញាសំខាន់សម្រាប់ SEO ភាសាច្រើនសម្រាប់ Google និងម៉ាស៊ីនស្វែងរកផ្សេងទៀត — មិនចាំបាច់មានកម្មវិធី SEO បន្ថែមទេ។','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge បញ្ចេញស្លាកសញ្ញា Open Graph និង Twitter Card ដើម្បីឲ្យ URL ដែលបានចែករំលែកបង្ហាញភាសាត្រឹមត្រូវ ចំណងជើង ពិពណ៌នា និងរូបភាពនៅលើវេទិកាសង្គម។','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge បញ្ចេញទិន្នន័យសម្រង់ Schema.org JSON-LD ដើម្បីឲ្យម៉ាស៊ីនស្វែងរកយល់ពីប្រភេទមាតិកា ភាសា និង metadata របស់អ្នក។ នេះគឺជាវិធីសាស្ត្រសំខាន់ក្នុងការប្រាស្រ័យទាក់ទងនូវការបញ្ជាក់ភាសាសម្រាប់មាតិកាភាសាច្រើនទៅ Google និងម៉ាស៊ីនស្វែងរកផ្សេងទៀត។','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge កំណត់សេវាកម្ម Gutenberg ពីរដោយលំនាំដើម ដើម្បីរក្សាការប្រព្រឹត្តិការណ៍នៃការប្រែសម្រួលឲ្យសមស្របគ្នានៅក្នុងភាសាផ្សេងៗ។ ជ្រើសរើសនៅទីនេះបើអ្នកត្រូវការសមត្ថភាពពេញលេញនៃ Gutenberg / FSE។','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge កំណត់សមាជិក WP_Query ទSecondary (វីហ្គេត sidebar, ប្លុកទំរង់, ការស្វែងរកកម្មវិធីផ្លាស់ទី) ទៅភាសាដែលសកម្មដោយបញ្ចូលកម្រង _lf_lang។ ប្រភេទប្រសាទដែលបានរាយនៅទីនេះត្រូវបានដកចេញពីកម្រងនោះ — ការស្វែងរករបស់ពួកវាតែងតែគ្មានការតម្រង។','Lingua Forge Settings'=>'ការកំណត់ Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge ប្រើស្រទាប់ cache ពីរដើម្បីចៀសវាងការហៅ API AI ដែលមិនចាំបាច់។ ប្រើផ្ទាំងខាងក្រោមសម្រាប់ពិនិត្យ និងគ្រប់គ្រងមួយៗ។','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge ប្រើស្រទាប់ cache ដោយឯករាជ្យពីរដើម្បីកាត់បន្ថយការហៅ API AI ដែលមិនចាំបាច់ឡើយ៖','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge ប្រើស្រទាប់ម៉ូដែលពីរពីអ្នកផ្គត់ផ្គង់:','Lingua Forge version'=>'កំណែ Lingua Forge','Lingua Forge — Quick Translate'=>'Lingua Forge — ប្រែរយៈពេលរហ័ស','Lingua Forge — Settings'=>'Lingua Forge — ការកំណត់','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'ម៉ូឌុលសង្គមចែករំលែក និង Open Graph ដែលមានសមត្ថភាពរួមបញ្ចូលគ្នានៅក្នុង Lingua Forge គ្រប់មុខងារ ដែលផ្ដល់ជូនដោយ mu-plugin ផងដែរ។ អ្នកអាចបិទ mu-plugin ដោយសុវត្ថិភាព។','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge, WordPress, និងជំនាន់ PHP; ប្រធានបទសកម្ម; រចនាសម្ព័ន្ធ URL; ភាសាគេហទំព័រ WP និងភាសាអត្ថបទសំខាន់។ សញ្ញាស្វ័យប្រវត្តិពណ៌ក្រហមនៅក្បែរភាសាគេហទំព័រ WP មានន័យថាវាមិនមែនជាភាសាអត្ថបទសកម្មទេ — ដោះសោវានៅក្នុងការកំណត់រចនាសម្ព័ន្ធ → ទូទៅ មុននឹងធ្វើអ្វីផ្សេងទៀត។','Link copied'=>'តំណភ្ជាប់បានចម្លង។','link(s)'=>'តំណភ្ជាប់','Links'=>'តំណភ្ជាប់','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'បញ្ជីនូវកម្មវិធី SEO ផ្នែកទីបីដែលសកម្ម។ Lingua Forge អាចកែប្រែលទ្ធផលរបស់វាពេលមានទាំងនេះ — មើលការកំណត់រចនាសម្ព័ន្ធ → SEO → សមត្ថភាពសម្រាប់ការបែងចែកតាមលក្ខណៈពិសេស។','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'បញ្ជីប្រភេទប្រកាសដែលមានប្រកាសដែលមិនមានតម្លៃ _lf_lang។ ប្រកាសដែលខ្វះស្លាកនេះមិនអាចមើលឃើញដោយតម្រងភាសាទាំងអស់។ ប្រើប៊ូតុងជួសជុលដើម្បីស្លាកវាជាភាសប្រភព ឬ Exclude ដើម្បីដកប្រភេទប្រកាសចេញពីការរុករកភាសាទាំងមូល។','Load available languages'=>'ផ្ទុកភាសាដែលអាចប្រើបាន','Load content'=>'ផ្ទុកមាតិកា។','Loaded from cache.'=>'បានផ្ទុកពី cache។','Loading…'=>'កំពុងផ្ទុក…','Locale only'=>'តែភាសា។','Locked — a conflicting SEO plugin is active. See the notice above.'=>'បានបិទ — មានកម្មវិធី SEO ដែលមានការប្រកួតប្រជែង។ សូមមើលការជូនដំណឹងខាងលើ។','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate រក្សាទុកការប្រែសម្រួលផ្ទាល់ខ្លួននៅក្នុង wp-content/languages/loco/ — តំបន់ដែលអាចត្រូវបានលុបចោលដោយការអាប់ដេត WP មួយ, ការតម្លើងកម្មវិធីផ្លាស់ទីឬការលុប Loco Translate។ ការចម្លងឯកសារនៅទីនេះផ្លាស់ទីឯកសារទៅក្នុងថត Lingua Forge i18n-overrides ដែលអាចរស់នៅបានជានិច្ច។','Loco Translate — Copy to Safe Storage'=>'Loco Translate — ចម្លងទៅសុវត្ថិភាព','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'សមត្ថភាព WordPress ទាបបំផុតដែលអាចបើកប្រើមុខងារ AI។ ការប tighten នេះលើគេហទំព័រដែលមានអ្នកនិពន្ធច្រើនជួយការពារអ្នកចូលរួមឬគណនីសាកល្បងពីការរត់ការហៅ AI ដែលបានបង់ប្រាក់។ ប្តូរតាមមុខងារតាមតម្រូវការតាមតម្រូវការ filter "linguaforge_required_capability"។','Maintenance'=>'ការថែទាំ','Maintenance Tab'=>'ផ្ទាំងថែទាំ','Make casual'=>'ធ្វើឱ្យសាមញ្ញ','Make concise'=>'ធ្វើឱ្យខ្លី','Make formal'=>'ធ្វើឱ្យផ្លូវការ','Manage your account, review usage, or top up credits:'=>'គ្រប់គ្រងគណនីរបស់អ្នក, ពិនិត្យការប្រើប្រាស់, ឬបន្ថែមប្រាក់កម្ចី៖','Mark citations needed'=>'សម្គាល់ការចាំបាច់សម្រួលចំណងជើង','Max context characters'=>'តួអក្សរឧបត្ថម្ភអតិបរមា','Max hints characters'=>'តួអក្សរបង្ហាញសេចក្ដីផ្តើម','Max input characters'=>'តួអក្សរចូលសរុបអតិបរមា','Max output tokens'=>'ចំនួនតួអក្សរចេញសរុប','Maximum characters accepted from the input field. Default: 8 000.'=>'តួអក្សរឧបត្ថម្ភអតិបរមាដែលអាចទទួលយកបានពីវាលបញ្ចូល។ លំនាំដើម: 8,000។','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'តួអក្សរឧបត្ថម្ភអតិបរមានៃមាតិកាប្រកាសដែលបានផ្តល់ឲ្យ AI ជាសេដ្ឋកិច្ចពេលដែលមិនមានសេចក្ដីផ្តើម។ លំនាំដើម: 6,000។','Maximum characters read from the Hints field. Default: 2 000.'=>'តួអក្សរឧបត្ថម្ភអតិបរមាដែលអាចអានបានពីវាលសេចក្ដីផ្តើម។ លំនាំដើម: 2,000។','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'ចំនួនតួអក្សរច្រើនបំផុតនៃមាតិកាបង្ហោះទៅ AI។ 0 មានន័យថាមិនមានកំណត់ — មាតិកពេញត្រូវបានផ្ញើជានិច្ច (ណែនាំ)។ កំណត់តម្លៃមិនមែនសូន្យ ប្រសិនបើអ្នកផ្គត់ផ្គង់របស់អ្នកមានបង្អួចបរិបទតឹង។ មានការព្រមានសរសេរទៅក្នុងកំណត់ហេតុកំហុស PHP នៅពេលដែលមាតិកាត្រូវបានកាត់។','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'ចំនួនតួអក្សរច្រើនបំផុតដែល AI អាចផលិតក្នុងចម្លើយមួយ។ ប្រសិនបើការប្រែប្រែត្រូវបានកាត់ចេញដោយស្ងាត់ បង្កើនតម្លៃនេះ។ លំនាំដើម: 16,000។','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'តួអក្សរឧបត្ថម្ភអតិបរមាដែល AI អាចផលិតបានក្នុងការរត់បង្កើតមួយ។ បង្កើនវាឡើង ប្រសិនបើអត្ថបទពេញត្រូវបានកាត់ចេញ។ លំនាំដើម: 8,192។','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'តួអក្សរឧបត្ថម្ភអតិបរមាដែល AI អាចផលិតបានក្នុងការប្រែសម្រួលយ៉ាងរហ័ស។ លំនាំដើម: 2,000។','Meta Description'=>'ការពិពណ៌នាមេតា','Meta description'=>'ការពិពណ៌នាផ្ទាល់ខ្លួន។','Meta Description, Excerpt Generator'=>'ម៉េតាអធិប្បាយ, អ្នកបង្កើតសេចក្ដីសង្ខេប','Meta Description, Excerpt Generator, quick translate'=>'ការពិពណ៌នាផ្សាយ, អ្នកបង្កើតសេចក្ដីសង្ខេប, ប្រែសម្រួលយ៉ាងរហ័ស','Metric'=>'មាត្រា។','Minimum role'=>'តួនាទីអប្បបរមា','Missing'=>'ខ្វះ','Missing pattern name or language.'=>'ខ្វះឈ្មោះលំនាំឬភាសា។','Mode'=>'របៀប','Model'=>'ម៉ូដែល','Model ID'=>'ID ម៉ូដែល','Model tier'=>'កម្រិតម៉ូដែល','Model tiers'=>'ស្រទាប់ម៉ូដែល','Models'=>'គំរូ','Modified'=>'បានកែប្រែ។','Most recent cached block'=>'ប្លុកដែលបានផ្ទុកចុងក្រោយ','Most recent cached response'=>'ចម្លើយដែលបានផ្ទុកចុងក្រោយ','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'ការរុករកភាសាច្រើន, SEO ភាសាច្រើនពេញលេញ (hreflang, Open Graph, Schema.org, sitemap), និងឧបករណ៍មាតិកា AI សម្រាប់ WordPress។ ការរកឃើញភាសា, ការរុករក URL, ការប្រែសម្រួល, ការបង្កើតមាតិកា និងស្រទាប់ SEO ពេញលេញ — គ្មានកម្មវិធីជំនួយផ្សេងទៀតត្រូវការ។','Multilingual SEO'=>'SEO ភាសាច្រើន','Multilingual SEO overview'=>'ទិដ្ឋភាពទូទៅ SEO ភាសាច្រើន','My Account'=>'គណនីរបស់ខ្ញុំ','Name'=>'ឈ្មោះ','Name displayed in this language. Leave empty to use the source name.'=>'ឈ្មោះដែលបង្ហាញក្នុងភាសានេះ។ ទុកវាអោយទទេដើម្បីប្រើឈ្មោះប្រភព។','Navigation'=>'ការរុករក','Navigation has no content to translate.'=>'មិនមានមាតិកាសម្រាប់បកប្រែ។','Navigation not found.'=>'មិនមានការរុករក។','Navigation posts are translated via the Router tab, not this button.'=>'ការប្រែប្រួលផ្លូវរបស់ការរុករកត្រូវបានបកប្រែតាមរយៈផ្ទាំង Router មិនមែនតាមប៊ូតុងនេះទេ។','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'ការប្រែសម្រួលការរុករកត្រូវការអ្នកផ្តល់សេវា AI សកម្ម។ កំណត់គន្លឹះ API នៅផ្ទាំង API Keys។','Navigations'=>'ការរុករក','Network error — could not reach the provider: %s'=>'កំហុសបណ្តាញ — មិនអាចទំនាក់ទំនងទៅកាន់អ្នកផ្គត់ផ្គង់បាន: %s','Network error — could not reach the WordPress AJAX endpoint.'=>'កំហុសបណ្តាញ — មិនអាចចូលដំណើរការចំណុច AJAX របស់ WordPress បាន។','Network error.'=>'កំហុសបណ្តាញ។','Never run'=>'មិនដែលរត់','No %s version found in this translation group.'=>'មិនមានកំណែ %s នៅក្នុងក្រុមការបកប្រែនេះទេ។','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'មិនចាំបាច់សកម្មភាពណាមួយទេ។ Google បានផ្ដាច់ចុងផ្លូវសម្រាប់សម្រង់សាយនៅខែមករា 2024 ហើយឥឡូវនេះរកឃើញផែនទីសាយតែម្នាក់ឯងតាមរយៈការណែនាំ robots.txt Sitemap: — ដែល LF បានកំណត់រួចហើយ។ Google នឹងយកវាទៅវិញនៅលើការរុករកបន្ទាប់។','No active plugins detected.'=>'មិនមានកម្មវិធីផ្លាកសញ្ញាដែលដំណើរការឡើយ។','No AI provider configured.'=>'មិនមានផ្គត់ផ្គង់ AI ត្រូវបានកំណត់។','No AI provider configured. Add an API key in Settings → API Keys.'=>'មិនមានអ្នកផ្ដល់ AI ត្រូវបានកំណត់។ បន្ថែមកូនសោ API នៅក្នុងការកំណត់ → កូនសោ API។','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'មិនមានការប្រើប្រាស់ AI ត្រូវបានកត់ត្រានៅក្នុងវិនដូដែលបានជ្រើស (%s)។ ជ្រើសរើសវែងជាងនេះខាងលើ។','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'មិនមានការប្រើប្រាស់ AI ត្រូវបានកត់ត្រាទេ។ នៅពេលកែសម្រួលចាប់ផ្តើមការបកប្រែ បង្កើតការពិពណ៌នាអំពីមេតា ឬប្រើលក្ខណៈពិសេស AI ផ្សេងទៀត សរុបនឹងបង្ហាញនៅទីនេះ។','No API key configured for this provider.'=>'មិនមានកូនសោ API បានកំណត់សម្រាប់អ្នកផ្គត់ផ្គង់នេះ។','No API key configured — enter your key in the AI Provider settings.'=>'គ្មានកូនសោ API ត្រូវបានកំណត់ — បញ្ចូលកូនសោរបស់អ្នកក្នុងការកំណត់រចនាសម្ព័ន្ធអ្នកផ្គត់ផ្គង់ AI។','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'គ្មានការណែនាំលំនាំមុនដែលមានស្រាប់ — លក្ខណៈពិសេស AI មួយៗប្រើការកំណត់លំនាំដើមរបស់ខ្លួន។ បញ្ចូលក្នុងវាលការណែនាំប្តូរតាមបំណងខាងក្រោមដើម្បីបន្ថែមច្បាប់ទូទៅសម្រាប់គេហទំព័ររបស់អ្នក។','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'មិនមានកម្មវិធី SEO ដែលមានការប្រកួតប្រជែងត្រូវបានរកឃើញ។ Lingua Forge កំពុងគ្រប់គ្រងការចេញផល SEO ដោយឡែក។','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'គ្មានប្រាក់កម្ចីនៅសល់ — បន្ថែមប្រាក់ក្នុងគណនី OpenAI របស់អ្នកនៅ platform.openai.com/account/billing។','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'មិនមានឯកសារប្តូរពិសេស Loco Translate ដែលបានរកឃើញទេ។ វានឹងបង្ហាញនៅទីនេះបន្ទាប់ពីអ្នករក្សាទុកការប្រែសម្រួលក្នុង Loco Translate។','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'មិនមានកម្មវិធី OG ខាងក្រៅត្រូវបានរកឃើញ។ LF កំពុងបញ្ចេញសំណុំ OG + Twitter Card ពេញលេញ។','No file was selected.'=>'មិនមានឯកសារណាមួយដែលបានជ្រើសរើស។','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'មិនមានចុះបញ្ជីវចនានុក្រមណាមួយផ្គូផ្គងនឹងតម្រងបច្ចុប្បន្នទេ។ សម្អាតតម្រងដើម្បីមើលឃើញចុះបញ្ជីទាំងអស់ ឬបន្ថែមចុះបញ្ជីថ្មីខាងក្រោម។','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'មិនមានចុះបញ្ជីវចនានុក្រមទេ។ បន្ថែមមួយខាងក្រោមដើម្បីចាប់ផ្តើមអនុវត្តន៍ពាក្យសម្ងាត់ក្នុងការប្រែប្រែ។','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'មិនមាន H1 ត្រូវបានរកឃើញ។ ជាទូទៅចំណងជើងប្រកាសគឺជា H1 — សូមបញ្ជាក់ថាតើប្រធានបទរបស់អ្នកកំពុងបញ្ចេញវាឬអត់។','No images found in content.'=>'មិនមានរូបភាពក្នុងមាតិកា។','No internal links found to update.'=>'មិនមានតំណភ្ជាប់ក្នុងផ្នែកខាងក្នុងដែលត្រូវអាប់ដេត។','No key'=>'គ្មានកូនសោ','No language-specific template parts found to map.'=>'មិនមានផ្នែកគំរូជាស្រេចសម្រាប់ផែនទី។','No LF meta description set — using excerpt/content.'=>'មិនមានការកំណត់ meta description — កំពុងប្រើសេចក្ដីអត្ថបទ/មាតិកា។','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'មិនមានច្បាប់សរសេរឡើងវិញ LF។ បញ្ចូល permalinks ប្រសិនបើនេះមិនមែនជាការរំពឹងទុក។','No links found.'=>'រកមិនឃើញតំណភ្ជាប់ណាមួយ។','No links found. Internal links improve crawlability and user navigation.'=>'មិនមានតំណភ្ជាប់។ តំណភ្ជាប់ក្នុងផ្នែកក្នុងបង្កើនភាពងាយស្រួលក្នុងការរុករក និងការរុករកអ្នកប្រើ។','No meta description found. Generate one via the AI meta description feature.'=>'មិនមាន meta description។ បង្កើតមួយដោយប្រើលក្ខណៈពិសេស AI meta description។','No navigation references needed updating.'=>'មិនមានការចាប់យកយោងនាវីហ្គេសិនដែលត្រូវការអាប់ដេត។','No override files uploaded yet.'=>'មិនមានឯកសារប្តូរណាមួយដែលបានផ្ទុកឡើងទេ។','No PHP limit'=>'គ្មានកំណត់ PHP','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'មិនមានឯកសារ robots.txt ផ្ទាល់ខ្លួនទេ។ WordPress កំពុងបង្កើតវាឡើងវិញ និងការណែនាំ Sitemap របស់ LF ត្រូវបានបញ្ចូលដោយស្វ័យប្រវត្តិ។','No published posts found for the selected filters.'=>'មិនមានប្រកាសផ្សាយទេសម្រាប់តម្រូវការជ្រើសរើស។','No response from AI provider. Check your API key and try again.'=>'មិនមានការឆ្លើយតបពីអ្នកផ្ដល់ AI។ សូមពិនិត្យកូនសោ API របស់អ្នក ហើយព្យាយាមម្តងទៀត។','No response from provider — check the error log for details.'=>'មិនមានការឆ្លើយតបពីអ្នកផ្គត់ផ្គង់ — សូមពិនិត្យកំណត់ហេតុកំហុសសម្រាប់ព័ត៌មានលម្អិត។','No secondary languages configured.'=>'មិនមានភាសាឧទ្ទេសន៍បានកំណត់។','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'មិនមានភាសាថ្នាក់ទីពីរត្រូវបានកំណត់។ ដំឡើងកញ្ចប់ភាសាខាងលើដើម្បីអាចប្រើប្រាស់គំរូស្ដង់ដារ។','No source content found to translate.'=>'មិនមានមាតិកាដែលប្រភពមកពីប្រភពមួយណាដើម្បីបកប្រែឡើយ។','No source page linked yet.'=>'មិនទាន់ភ្ជាប់ទំព័រខ្សែប្រភពទេ។','No template part references needed updating.'=>'មិនមានការចាប់យកផ្នែកគំរូដែលត្រូវការអាប់ដេត។','No terms found.'=>'មិនមានពាក្យណាមួយ។','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'មិនមានកម្មវិធីផ្នែកទីបីសម្រាប់ SEO ត្រូវបានរកឃើញ។ Lingua Forge គ្រប់គ្រងផលិតផល SEO ភាសាច្រើនទាំងអស់។','No title set.'=>'មិនមានចំណងជើងកំណត់។','No translated content found. The sitemap will populate once posts have been translated.'=>'មិនមានមាតិកាដែលបានបកប្រែទេ។ ផែនទីសាយនឹងបំពេញពេលដែលមានការបកប្រែប្រកាស។','No translation found — analyzed the source language version.'=>'មិនមានការបកប្រែទេ — បានវិភាគចំណុចប្រភពភាសា។','No {lang} translation registered (TRID missing)'=>'មិនមានការចុះបញ្ជីបកប្រែ {lang} (TRID ខ្វះ)។','No — WooCommerce integration class not loaded'=>'មិនមាន — ថ្នាក់ចង្វាក់សមាសភាព WooCommerce មិនបានផ្ទុកឡើង','not a content language — see notice above'=>'មិនមែនជាភាសាអត្ថបទ — សូមមើលការជូនដំណឹងខាងលើ។','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'មិនទាន់បានបង្កើត។ ផែនទីសាយត្រូវបានបង្កើតនៅលើការអញ្ជើញដំបូងទៅ URL ផែនទីសាយ ហើយបាន cache សម្រាប់ 24 ម៉ោង។','Notes'=>'ចំណាំ','Nothing — all types disabled'=>'អ្វីៗគ្រប់យ៉ាងបានបិទ។','Notice message'=>'សារជូនដំណឹង','Notice settings'=>'ការកំណត់ការជូនដំណឹង','Notify search engines'=>'ជូនដំណឹងម៉ាស៊ីនស្វែងរក។','Numeric permalink structure is not supported.'=>'រចនាសម្ព័ន្ធ permalink លេខមិនគាំទ្រ','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'ស្លាក OG/Twitter Card: ដំណោះស្រាយដោយម៉ូឌុល Open Graph របស់ LF (SEO → Open Graph & Twitter Cards)។','Oldest cached block'=>'ប្លុកចាស់បំផុត','Oldest cached response'=>'ចម្លើយចាស់បំផុត','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'ចម្លងមួយចុចសម្រាប់សង្ខេបប្រព័ន្ធជាអក្សរទាំងអស់ដែលគ្របដណ្តប់ផ្នែកខាងលើ។ បិទវានៅក្នុងបញ្ហា GitHub ឬសំណើរឧបត្ថម្ភ ដើម្បីឲ្យឃើញបរិយាកាសពេញលេញក្នុងមួយចំណុច។','Only .mo files are accepted.'=>'មានតែ .mo ឯកសារតែអាចទទួលយកបាន។','Open an issue →'=>'បើកបញ្ហា →','Open Graph'=>'Open Graph។','Open Graph &amp; Twitter Cards'=>'កាត Open Graph &amp; Twitter','Open Graph output'=>'ការបញ្ចេញ Open Graph។','Open Graph settings saved.'=>'ការកំណត់ Open Graph បានរក្សាទុក។','Open Search Console →'=>'បើក Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'បើកសន្លឹកចែករំលែក Web Share ដើម (iOS, Android, បណ្តាញខ្លះ)។ វាផ្ដល់ជូនវិញទៅកាន់ចម្លងច្បាប់បើមិនគាំទ្រឡើយ។','OpenAI (GPT)'=>'OpenAI (GPT)','OpenAI Platform'=>'វេទិកា OpenAI','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'បរិយាយបន្ថែមសម្រាប់អ្នកកែសម្រួល (ឧ. "ASIC = ប្រព័ន្ធសមាសធាតុប្រើប្រាស់ពិសេស; រក្សាទុកនៅក្នុងភាសាអង់គ្លេសក្នុងបរិបទបច្ចេកទេស").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'ជាជម្រើស។ Bing បានអានការណែនាំ Sitemap: ពី robots.txt ហើយនេះគ្រាន់តែជាការបញ្ជាក់ឲ្យបង្រៀនការរុករកឲ្យឆាប់ឡើងវិញ។','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'ជាជម្រើស។ Yandex បានអានការណែនាំ Sitemap: ពី robots.txt ហើយនេះគ្រាន់តែជាការបញ្ជាក់ឲ្យបង្រៀនការរុករកឲ្យឆាប់ឡើងវិញ។','Order storage'=>'ការរក្សាទុកការបញ្ជាទិញ','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'បញ្ជាទិញក្នុង wp_posts — ធានាថា shop_order ត្រូវបានដកចេញពីការចងចាំ LF។','Output'=>'លទ្ធផល','Output Article or WebPage schema on singular posts and pages'=>'បញ្ចេញ schema Article ឬ WebPage នៅលើប្រកាស និងទំព័រពិសេស។','Output hreflang tags in wp_head'=>'បញ្ចេញស្លាក hreflang នៅក្នុង wp_head។','Output mode'=>'របៀបបញ្ចេញ។','Output Open Graph tags in wp_head'=>'បញ្ចេញស្លាក Open Graph នៅក្នុង wp_head។','Output Product schema on WooCommerce product pages'=>'បញ្ចេញ schema ផលិតផលនៅលើទំព័រផលិតផល WooCommerce។','Output Schema.org JSON-LD in wp_head'=>'បញ្ចេញ JSON-LD Schema.org នៅក្នុង wp_head។','Output tokens'=>'Token ផលចេញ','Output WebSite schema on the front page and blog index'=>'បញ្ចេញ schema WebSite នៅលើទំព័រដើម និងបញ្ជីប្លុក។','Overall SEO score'=>'ពិន្ទុ SEO សរុប។','overridden'=>'បានផ្លាស់ប្តូរ','Override file deleted.'=>'ឯកសារប្តូរត្រូវបានលុប។','Override file uploaded successfully.'=>'ឯកសារប្តូរត្រូវបានផ្ទុកឲ្យបានជោគជ័យ។','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'បដិសេធកំណត់សេចក្តីប្រើប្រាស់ AI សម្រាប់ការបកប្រែ និងការបង្កើតមាតិកានៅលើទំព័រនេះ។ លក្ខណៈពិសេសផ្សេងទៀតតែងតែប្រើកំណត់សេចក្តីប្រើប្រាស់សកល។','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'បដិសេធកំណត់សេចក្តីប្រើប្រាស់ AI សម្រាប់ការបកប្រែ និងការបង្កើតមាតិកានៅលើទំព័រនេះ។ ការណែនាំផ្ទាល់ខ្លួនទូទៅសម្រាប់គេហទំព័រមានការបន្ថែមនៅលើសំណើរៀងរាល់ការស្នើសុំ។','Overview'=>'ទិដ្ឋភាពទូទៅ','Page'=>'ទំព័រ','Part'=>'ផ្នែក','Paste a footnote, sentence, or any snippet here…'=>'ចម្លងចុះសម្គាល់, ប្រយោគ, ឬចំណុចណាមួយនៅទីនេះ…','Paste text, or select text in the editor first…'=>'ចម្លងអត្ថបទ ឬ ជ្រើសអត្ថបទនៅក្នុងកម្មវិធីកែសម្រួលជាមុន…','Paste text, or select text on the page first…'=>'ចម្លងអត្ថបទ ឬ ជ្រើសអត្ថបទនៅលើទំព័រជាមុន…','Paste your API key…'=>'បិទកូនសោ API របស់អ្នក…','Path prefix (/de/)'=>'ផ្លូវបន្ថែម (/de/)','Path prefix — example.com/de/'=>'ផ្លូវ prefix — example.com/de/','Path routing requires a post-name based permalink structure. Change it in'=>'ការរុករកផ្លូវត្រូវការរចនាសម្ព័ន្ធ permalink ដែលផ្អែកលើឈ្មោះអត្ថបទ។ ផ្លាស់ទីវានៅក្នុង','Pattern'=>'គំរូ','Pattern has no content to translate.'=>'លំនាំមិនមានមាតិកាសម្រាប់បកប្រែ។','Pattern not found.'=>'លំនាំមិនមាន។','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'លំនាំបានបកប្រែ និងរក្សាទុក។ ចម្លងមាតិកាទៅក្នុងអត្ថបទ CPT របស់អ្នកតាមកម្មវិធីបញ្ចូលលំនាំឬប្រើវាជាចំណុចចាប់ផ្តើមសម្រាប់ប្លុកដែលអាចប្រើបាន។','Pattern translation failed.'=>'ការបកប្រែគំរូបរាជ័យ។','Payment required — your account has no remaining credits.'=>'ការទូទាត់ត្រូវការ — គណនីរបស់អ្នកមិនមានឥណទាននៅសល់ទេ។','Per-Post Analysis'=>'វិភាគតាមអត្ថបទ','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'ការវិភាគតាមអត្ថបទសម្រាប់ការប្រែសម្រួលដែលបង្កើតដោយ AI, ការពិពណ៌នាផ្សេងៗ, សេចក្ដីសង្ខេប និងមាតិកា។ ការចុះបញ្ជីត្រូវបានលុបចោលដោយស្វ័យប្រវត្តិពេលមានការផ្លាស់ទីមាតិកាឬម៉ូដែល/ផ្គត់ផ្គង់ AI។','Permalink rules flushed successfully.'=>'ច្បាប់ Permalink បានលុបចោលដោយជោគជ័យ។','Permalink Structure'=>'រចនាសម្ព័ន្ធ Permalink','Permalink structure is compatible with Lingua Forge path routing.'=>'រចនាសម្ព័ន្ធ Permalink សមត្ថភាពជាមួយផ្លូវ Lingua Forge','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'លុបចោលគំរូទាំងអស់, ផ្នែកគំរូ, លំនាំ, ម៉ឺនុយនាវីហ្គេសិន, អត្ថបទ, ទំព័រ, ប្រភេទអត្ថបទផ្ទាល់ខ្លួន, ផលិតផល, និងការប្រែប្រួលផលិតផលដែលពាក់ព័ន្ធនឹងភាសានេះ។ ក៏ដូចជាលុបឯកសារផ្ទុកភាសា WordPress ដូច្នេះភាសានេះមិនបង្ហាញនៅក្នុងអ្នកចងចាំផ្លូវ។ សកម្មភាពនេះមិនអាចត្រឡប់ក្រោយបានទេ។','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'លុបចោល %s ដោយសេរី? នេះនឹងលុបចោលមាតិកាដែលបានបកប្រែសម្រាប់ភាសានេះ ហើយមិនអាចត្រឡប់ក្រោយបានទេ។','Permission denied.'=>'ការអនុញ្ញាតបានបដិសេធ។','Persuasive'=>'ការជំរុញ','PHP constant'=>'អថេររបស់ PHP','PHP max_execution_time'=>'ពេលវេលាអនុវត្ត PHP สูงสุด','PHP memory_limit'=>'កម្រិតអង្គចងចាំ PHP','PHP version'=>'កំណែ PHP','Pin on Pinterest'=>'ចុចនៅលើ Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'កំណត់ពាក្យដែលមិនត្រូវប្រែសម្រួល ឬត្រូវតែបង្ហាញជារបៀបជាក់លាក់ (ឧ. ឈ្មោះម៉ាក, ឈ្មោះផលិតផល, អក្សរកាត់). កំណត់ពាក្យសព្ទត្រូវបានបញ្ចូលទៅក្នុងសំណើប្រែសម្រួល AI សម្រាប់លក្ខណៈពិសេសទាំងអស់: ប្រែសម្រួលអត្ថបទ, ពិពណ៌នា, សេចក្ដីសង្ខេប, និងការប្រែសម្រួលគំរូ FSE។','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'ភាសាសាមញ្ញ','Plain permalinks are not supported.'=>'Permalinks ធម្មតាមិនគាំទ្រ','Please enter some instructions first…'=>'សូមបញ្ចូលការណែនាំមួយចំនួនជាមុន…','Please enter some text first…'=>'សូមបញ្ចូលអត្ថបទមួយចំនួនជាមុន…','Plugin'=>'ផ្លាកសញ្ញា','Post'=>'អត្ថបទ','Post not found or not published.'=>'អត្ថបទមិនមានឬមិនបានបោះពុម្ពផ្សាយ។','Post not found.'=>'អត្ថបទមិនមាន។','Post on X / Twitter'=>'អត្ថបទនៅលើ X / Twitter','Post type'=>'ប្រភេទអត្ថបទ','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'ស្លាកប្រភេទប្រកាសដែលបែងចែកដោយក្បៀសឬបន្ទាត់ថ្មី។ ការផ្លាស់ប្តូរនឹងមានប្រសិទ្ធភាពភ្លាមៗនៅពេលរក្សាទុក — មិនចាំបាច់បញ្ចូល permalink។','Post Types'=>'ប្រភេទ post','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'អត្ថបទដែលមិនមាន _lf_lang មើលឃើញសម្រាប់ភាសាទាំងអស់របស់ Lingua Forge។ វាអាចកើតឡើងពេលនាំចូលឬបង្កើតមុនពេលប្លុកចាប់ផ្តើម។','Prefilled from excerpt. Edit to override.'=>'បានបំពេញពីការបង្ហាញជាមុន។ កែសម្រួលដើម្បីបដិសេធ។','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'តម្លៃ និងភាពអាចប្រើបានតែងតែបង្ហាញពីផលិតផលប្រភពភាសា (ម៉ូដែលស្តុកចែករំលែក)។ ស្លាកសញ្ញាត្រូវបានបញ្ចេញតែពេលដែលម៉ូឌុល Open Graph របស់ LF ត្រូវបានកំណត់ជា "ពេញ" ឬ "ស្វ័យប្រវត្តិ" ដោយគ្មានកម្មវិធី SEO ដែលផ្ទុយគ្នា។','Primary content language'=>'ភាសាអត្ថបទសំខាន់','Primary Language'=>'ភាសាចម្បង','Primary language'=>'ភាសាចម្បង','Primary language saved.'=>'ភាសាចម្បងបានរក្សាទុក។','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'ភាសាសំខាន់: ភាសាដែលអត្ថបទរបស់អ្នកសរសេរឡើង។ ការប្រែសម្រួលទាំងអស់ត្រូវបានផលិតពីភាសានេះ; ការផ្លាស់ទីវាមិនផ្លាស់ទី ឬលុបចោលអត្ថបទណាមួយ។','Processing…'=>'កំពុងដំណើរការ…','Product'=>'ផលិតផល','Product / eCommerce'=>'ផលិតផល / អ៊ីមើស','Product Open Graph'=>'Open Graph ផលិតផល','Product — WooCommerce product pages'=>'ផលិតផល — ទំព័រផលិតផល WooCommerce','Profile'=>'ប្រវត្តិរូប','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'ប្រវត្តិរូបអាចបត់បែនកម្រិតនិងទំងន់ទៅតាមប្រភេទមាតិកាដែលកំពុងវិភាគ។ ប្រវត្តិរូបត្រូវបានដោះសោដោយស្វ័យប្រវត្តិ; អ្នកអាចបដិសេធវា​តាមការវិភាគមួយពី dropdown ប្រវត្តិរូប។','Provider'=>'អ្នកផ្គត់ផ្គង់','Provider error (HTTP %1$d): %2$s'=>'កំហុសអ្នកផ្គត់ផ្គង់ (HTTP %1$d): %2$s','Provider returned no response. Check the WordPress error log for details.'=>'អ្នកផ្គត់ផ្គង់មិនបានផ្តល់ចម្លើយទេ។ ពិនិត្យកំណត់ត្រាកំហុស WordPress សម្រាប់ព័ត៌មានលម្អិត។','Provider service temporarily unavailable — try again in a moment.'=>'សេវាកម្មអ្នកផ្គត់ផ្គង់មិនអាចប្រើបានជាបណ្តោះអាសន្ន — សូមព្យាយាមម្តងទៀតក្នុងពេលខាងមុខ។','Quality'=>'គុណភាព','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'គុណភាព (លំនាំដើម — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'គុណភាព (Sonnet / GPT-4o / Gemini Pro)','Quality model'=>'គំរូគុណភាព','Quality: used for post translation and content generation — higher quality, higher cost.'=>'គុណភាព: ប្រើសម្រាប់ការប្រែសម្រួលអត្ថបទ និងការបង្កើតមាតិកា — គុណភាពខ្ពស់, តម្លៃខ្ពស់។','Query Filter Exclusions'=>'ការលើកលែងតម្រងសំណួរ','Quick Translate'=>'បកប្រែរហ័ស','Quick Translation'=>'ការប្រែប្រែរហ័ស','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'ការប្រែប្រែរហ័សត្រូវបានប្រើសម្រាប់របៀបខ្លី/ផ្លាក — ប្រយោគខ្លីដែលត្រូវបានប្រែប្រែតាមតម្រូវការ ពី Toolbar, អ្នកកែសម្រួល ឬ popovers ប្លុក។ វាប្រើការកំណត់ផ្សេងទៀតសម្រាប់ការប្រែប្រែទំព័រពេញ ដើម្បីរក្សាការឆ្លើយតបឲ្យមានល្បឿន និងថ្លៃសមរម្យ។','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'កំណត់អត្រា — មានការផ្ញើសំណើច្រើនពេកទៅអ្នកផ្គត់ផ្គង់; សូមរងចាំមួយភ្លែតហើយព្យាយាមម្តងទៀត។','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'បើកវិញការចាក់សោ Gutenberg\'s canLockBlocks។ មានប្រយោជន៍សម្រាប់គំរូកែសម្រួលដែលត្រូវការការពារអ្នកចូលរួមពីការផ្លាស់ទី ឬលុបចោល Block ជាក់លាក់។','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'បើកវិញការគាំទ្ររបៀបគំរូ។ ជាស្នូលសម្រាប់ការងារប្រើប្រាស់ Full-Site-Editing ដែលមានការបដិសេធរបៀបគំរូនៅលើកម្រិតប្រកាស។','Re-generates and updates the cached result.'=>'បង្កើតឡើងវិញ និងធ្វើឱ្យទិន្នន័យដែលបានរក្សាទុកឱ្យទាន់សម័យ។','Re-scan'=>'ស្កេនឡើងវិញ','Re-scanning…'=>'កំពុងស្កេនឡើងវិញ…','Re-translate'=>'បកប្រែម្ដងទៀត','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'វិភាគសម្រាប់ការតំឡើងបច្ចុប្បន្ន។ មិនមានការកំណត់ណាមួយត្រូវបានផ្លាស់ទីនៅទីនេះ — ប្រើវាដើម្បីផ្ទៀងផ្ទាត់ការកំណត់រចនាសម្ព័ន្ធ, សម្គាល់បញ្ហា, និងប្រមូលព័ត៌មានសម្រាប់របាយការណ៍កំហុស។','Reading time'=>'ពេលវេលាអាន','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'បញ្ជូនភ្ញៀវទៅភាសាដែលពួកគេចង់បានដោយផ្អែកលើ header Accept-Language របស់កម្មវិធីរុករក','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'កែលម្អបន្ថែម — ឧ. "ធ្វើឲ្យខ្លីសង្ខេប" ឬ "ប្រើសម្លេងផ្លូវការ"…','Refine further:'=>'កែលម្អបន្ថែម៖','Refinement'=>'ការកែលម្អ (អ្នកបកប្រែ: %d ជាលេខចំនួននៃការកែលម្អ)','Refinement failed — please try again.'=>'ការកែលម្អបរាជ័យ — សូមព្យាយាមម្តងទៀត។','Refining…'=>'កំពុងកែលម្អ…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'បង្កើតឡើងវិញច្បាប់សរសេរ WordPress ដើម្បីឲ្យ URL prefixes, slugs ភាសា និងការសរសេរអារង់សម្របសម្រួលគ្នា។ ត្រូវការបន្ទាប់ពីផ្លាស់ទីភាសាសំខាន់ ឬបន្ថែមការគាំទ្រភាសាថ្មី។','Remove stored key'=>'យកកូនសោដែលបានផ្ទុកចេញ','Repair failed.'=>'ការជួសជុលបរាជ័យ។','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'ជួសជុលស្លាកពេលរៀបចំប្រកាសដែលអាចផ្លាស់ទីបានខាងលើជាមួយ _lf_lang = %s។ ប្រកាសក្នុងប្រភេទប្រកាសដែលមិនត្រូវបានចងចាំមិនត្រូវបានប៉ះពាល់។ ប្រើវានៅក្រោយនាំចូលមាតិកាឬនៅលើការចាប់ផ្តើមដំបូង — កុំប្រើជាឧបករណ៍ផ្លាស់ទីភាសាជាច្រើន។','Repair Template Metadata'=>'ជួសជុលមេតាដាតា','Repair template metadata'=>'ជួសជុលមេតាដាតា','Repair — assign _lf_lang = %s to all routable posts above'=>'ជួសជុល — ផ្ដល់ _lf_lang = %s ទៅកាន់ប្រកាសដែលអាចផ្លាស់ទីបានខាងលើ','Repairing…'=>'កំពុងជួសជុល…','Report an issue on GitHub'=>'រាយការណ៍បញ្ហានៅលើ GitHub','Request failed — please try again.'=>'សំណើបរាជ័យ — សូមព្យាយាមម្តងទៀត។','Request failed.'=>'ការស្នើសុំបរាជ័យ។','Request failed. Check your connection.'=>'ការស្នើសុំបរាជ័យ។ សូមពិនិត្យការតភ្ជាប់របស់អ្នក។','Request failed. Please try again.'=>'ការស្នើសុំបរាជ័យ។ សូមព្យាយាមម្តងទៀត។','Requests'=>'សំណើរ','requests / day'=>'សំណើរ / ថ្ងៃ','Reset'=>'កំណត់ឡើងវិញ','Result will appear here…'=>'លទ្ធផលនឹងបង្ហាញនៅទីនេះ…','Retranslate'=>'បកប្រែម្ដងទៀត','Retranslating…'=>'កំពុងបកប្រែម្ដងទៀត…','Review carefully — links and slugs not updated.'=>'ពិនិត្យយ៉ាងប្រុងប្រយ័ត្ន — តំណភ្ជាប់ និងស្លាកឈ្មោះមិនបានធ្វើបច្ចុប្បន្នភាព។','Review translation before applying'=>'ពិនិត្យការប្រែសម្រួលមុនពេលអនុវត្ត','Revise'=>'កែសម្រួល','Revision'=>'ការកែសម្រួល','Revision Type'=>'ប្រភេទការកែសម្រួល','Rewrite Rules'=>'ច្បាប់សរសេរ מחדש','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt បានធ្វើបច្ចុប្បន្នភាពជាមួយសេចក្តីណែនាំ Sitemap។','Router'=>'Router','Router Tab'=>'ផ្ទាំងអ្នកផ្លាស់ប្តូភាសា','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'អនុវត្តការត្រួតពិនិត្យ SEO ពេញលេញលើអត្ថបទផ្សាយទាំងអស់សម្រាប់ភាសាមួយឬច្រើន។ ពិន្ទុត្រូវបានរក្សាទុកក្នុងមួយអត្ថបទ និងបង្ហាញនៅក្នុងស្លាកសញ្ញា​ជួរឈរភាសានៅក្នុងបញ្ជីអត្ថបទ។','Run AI Analysis'=>'រត់វិភាគ AI','Save'=>'រក្សាទុក','Save analysis settings'=>'រក្សាទុកការកំណត់វិភាគ','Save Debug Setting'=>'រក្សាទុកការកំណត់ Debug','Save Hreflang Settings'=>'រក្សាទុកការកំណត់ Hreflang','Save Open Graph Settings'=>'រក្សាទុកការកំណត់ Open Graph','Save Router Settings'=>'រក្សាទុកការកំណត់ Router','Save Schema.org Settings'=>'រក្សាទុកការកំណត់ Schema.org','Save Settings'=>'រក្សាទុកការកំណត់','Save Sitemap Settings'=>'រក្សាទុកការកំណត់ Sitemap','Save Social Share Settings'=>'រក្សាទុកការកំណត់ការចែករំលែកសង្គម','Save the post to persist changes.'=>'រក្សាទុកអត្ថបទដើម្បីរក្សាការផ្លាស់ប្តូរ។','Save Uninstall Setting'=>'រក្សាទុកការកំណត់លុបកម្មវិធី','Save WooCommerce SEO Settings'=>'រក្សាទុកការកំណត់ SEO សម្រាប់ WooCommerce','Saved to the meta description field when you apply.'=>'បានរក្សាទុកទៅក្នុងវាលការពិពណ៌នាមេតា នៅពេលអ្នកអនុវត្ត។','Scan failed: '=>'ការស្កេនបរាជ័យ: ','Scan request failed. Please try again.'=>'សំណើរស្កេនបរាជ័យ។ សូមព្យាយាមម្តងទៀត។','Scanning posts for broken language links…'=>'កំពុងស្កេនអត្ថបទសម្រាប់តំណភ្ជាប់ភាសាខូច…','Schema output deferred.'=>'លទ្ធផល Schema បានផ្អាក។','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'លទ្ធផល Schema.org','Schema.org settings saved.'=>'ការកំណត់ Schema.org បានរក្សាទុក។','Score'=>'ពិន្ទុ','Score computation'=>'ការគណនាកะแนน','Score history and badges'=>'ប្រវត្តិកะแนนនិងសញ្ញាបត្រ','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'ពិន្ទុគឺសញ្ញា មិនមែនជាការសម្រេចចិត្ត។ មាតិកាខ្លះមានកំណត់ក្នុងរចនាសម្ព័ន្ធ — ទំព័រខ្លីណាស់, ទំព័រចុចចូលដែលមានអត្ថបទខ្លី ឬទំព័រដែលមានគោលបំណងជាឧបករណ៍នាវីហ្គេសិនអាចមានពិន្ទុទាប។ ប្រើសេចក្ដីមើលនេះដើម្បីរកឃើញភាពសមស្របពិតប្រាកដក្នុងភាសា មិនមែនសម្រាប់តាមដានលេខ។','Search'=>'ស្វែងរក','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Console ស្វែងរកមានប្រយោជន៍សម្រាប់តាមដានកំហុសក្នុងការចងចាំ និងការគ្រប់គ្រង, ប៉ុន្តែមិនចាំបាច់សម្រាប់ការរកឃើញទេ។','Search Results'=>'លទ្ធផលស្វែងរក','Sections'=>'ផ្នែក','Security check failed — file path is not permitted.'=>'ការត្រួតពិនិត្យសុវត្ថិភាពបរាជ័យ — ផ្លូវឯកសារមិនអនុញ្ញាត។','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'មើលការកំណត់ → SEO → សមត្ថភាពសម្រាប់តារាងសមត្ថភាពលម្អិត។','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'ជ្រើសរើសភាសាដើម្បីគ្រប់គ្រងគំរូ FSE, ផ្នែកគំរូ និងម៉ឺនុយនាវីហ្គេស។','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'ជ្រើសអត្ថបទមួយ ហើយអនុវត្តការត្រួតពិនិត្យ SEO លម្អិត ដើម្បីមើលលទ្ធផលតាមមាត្រ និងពិន្ទុសម្រាប់ធាតុជាក់លាក់នោះ។','Select language'=>'ជ្រើសភាសា','Send via Telegram'=>'ផ្ញើតាម Telegram','Send via WhatsApp'=>'ផ្ញើតាម WhatsApp','SEO'=>'SEO','SEO Analysis'=>'វិភាគ SEO','SEO character-count info'=>'ព័ត៌មានចំនួនតួអក្សរ SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'កម្មវិធី SEO ដែលបានរកឃើញ: %s។ LF កំពុងបញ្ចេញ og:locale និង og:locale:alternate តែប៉ុណ្ណោះ; កម្មវិធីដែលបានរកឃើញគ្រប់ OG ត្រូវបានគ្រប់គ្រង។','SEO Plugins'=>'កម្មវិធីផ្នែក SEO','SEO plugins and conflict avoidance:'=>'កម្មវិធី SEO និងការជៀសវាងការប្រឈមមុខ៖','SEO Score System'=>'ប្រព័ន្ធពិន្ទុ SEO','SEO Scores'=>'ពិន្ទុ SEO','SEO Tab'=>'ផ្ទាំង SEO','Server setup (subdomain)'=>'ការរៀបចំម៉ាស៊ីនបម្រើ (ឧបករណ៍បណ្តាញរង)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'កំណត់សីតុណ្ហភាព AI ដោយលំនាំដើមសម្រាប់គេហទំព័រ។ ប្រសិនបើចង់ផ្លាស់ប្តូរពីនេះ អ្នកអាចកំណត់តាមប្រកាសដោយប្រើប្រអប់មេតា Lingua Forge។','Settings'=>'ការកំណត់','Settings saved.'=>'ការកំណត់ត្រូវបានរក្សាទុក។','Settings → General → Site Language'=>'ការកំណត់ → ទូទៅ → ភាសាគេហទំព័រ','Settings → Permalinks'=>'ការកំណត់ → Permalinks','Share on Facebook'=>'ចែករំលែកនៅលើ Facebook','Share on LinkedIn'=>'ចែករំលែកនៅលើ LinkedIn','Share on Mastodon'=>'ចែករំលែកនៅលើ Mastodon','Share via email (mailto:)'=>'ចែករំលែកតាមអ៊ីមែល (mailto:)','Shared / compatibility mode'=>'របៀបចែករំលែក / សមត្ថភាពសម្របសម្រួល','Shop'=>'ហាង','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'មាតិកាខ្លី (3 ប្រយោគឬតិចជាងនេះ) មិនត្រូវបានពិន័យសម្រាប់ការខ្វះចំណងជើងរងទេ។ ទំព័រខ្លីមិនមានអត្ថប្រយោជន៍ពីរចនាសម្ព័ន្ធចំណងជើងដែលបានបង្ខំ។','Show home link'=>'បង្ហាញតំណភ្ជាប់ទៅផ្ទះ','Shown when no translation exists for the visitor\'s language.'=>'បង្ហាញពេលដែលមិនមានការប្រែសម្រួលសម្រាប់ភាសារបស់អ្នកទេសចរ។','Single'=>'តែមួយ','Single %s'=>'តែមួយ %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'ចំណងជើងពាក្យតែមួយ (%d តួអក្សរ) — បន្ថែមពាក្យទីពីរជួយបង្កើនភាពច្បាស់លាស់ និងការគ្រប់គ្រងពាក្យគន្លឹះ។','Single: %s'=>'តែមួយ: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'កម្រិតសំណើរពេញមួយវេបសាយក្នុងមួយថ្ងៃ UTC (រាប់ទាំងការប្រែប្រែ Toolbar និងការកែសម្រួលប្លុក)។ កំណត់ឡើងវិញនៅម៉ោង ០០:០០ UTC។ កំណត់ជា 0 ដើម្បីបិទកំណត់នេះ។','Sitemap'=>'ផែនទីសាយ','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'បានលុបចោល cache ផែនទីសាយ។ វានឹងត្រូវបានបង្កើតឡើងវិញនៅលើការអញ្ជើញចូលទៅកាន់ URL ផែនទីសាយក្រោយ។','Sitemap output'=>'លទ្ធផលផែនទីសាយ','Sitemap settings saved.'=>'បានរក្សាទុកការកំណត់ផែនទីសាយ។','Sitemap URL'=>'URL ផែនទីសាយ','Size'=>'ទំហំ','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'ចែករំលែកស្លាកសញ្ញាសង្គម: URL: ត្រូវបានគ្រប់គ្រងដោយ LF\'s Social Share (SEO → Social Share)','Social Share'=>'ការចែករំលែកសង្គម','Social Share settings saved.'=>'ការកំណត់ការចែករំលែកសង្គមបានរក្សាទុក។','Some link fixes failed.'=>'ការជួសជុលតំណភ្ជាប់ខ្លះបរាជ័យ។','Some nav ref fixes failed.'=>'ការជួសជុលយោងនាវីហ្គេសិនខ្លះបរាជ័យ។','Some part fixes failed.'=>'ការជួសជុលផ្នែកខ្លះបរាជ័យ។','Some parts could not be created.'=>'ផ្នែកខ្លះមិនអាចបង្កើតបាន។','Some templates could not be created.'=>'មានគំរូខ្លះមិនអាចបង្កើតបាន។','Some translations failed.'=>'ការបកប្រែខ្លះបរាជ័យ។','source'=>'ប្រភព','Source file not found.'=>'រកមិនឃើញឯកសារប្រភព។','Source lang'=>'ភាសាដើម','Source language'=>'ភាសាដើម','Source term'=>'ពាក្យប្រភព','Source title'=>'ចំណងជើងប្រភព','Standard'=>'ស្តង់ដារ','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'ប្រើសីតុណ្ហភាពដែលបានកំណត់សម្រាប់មុខងារនីមួយៗ: ប្រែសម្រួល T=0.2 (ច្បាស់), ប្រែសម្រួលរហ័ស T=0.4, អ្នកបង្កើតមាតិកា T=0.6 (ច្នៃប្រឌិត)។ ប្រើសេតុភាពផ្សេងទៀតសម្រាប់គ្រប់មុខងារ។','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'ចាប់ផ្តើមវាយពាក្យនៅក្នុងវាលណាមួយដើម្បីមើលការណែនាំម៉ូដែល ឬប្រើតារាងយោងខាងក្រោម។ ម៉ូដែលគុណភាពទាបនិងមធ្យម (Haiku, GPT-4o mini, Gemini Flash) គ្រប់គ្រាន់សម្រាប់ការប្រែសម្រួលនិងបង្កើតមាតិកា — ម៉ូដែល "max" សំខាន់ៗបន្ថែមចំណាយជាមួយនឹងគុណភាពតិចតួចសម្រាប់អត្ថបទមានរចនាសម្ព័ន្ធ។','Status'=>'ស្ថានភាព','Status / Actions'=>'ស្ថានភាព / សកម្មភាព','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'រក្សាទុកចម្លើយ AI ដោយផ្ទាល់សម្រាប់ការឆ្លើយតបដោយផ្អែកលើកូនសោមាត្រា, គូភាសា, អ្នកផ្គត់ផ្គង់, ម៉ូដែល, និងការកំណត់ជាមុន។ ការចូលប្រើ cache ត្រូវបានផ្អែកលើការផ្លាស់ប្តូរនៃមាត្រាអត្ថបទប្រភព។ លុបចោលចូលប្រើបុគ្គលឬ cache ទាំងមូលពីផ្ទាំងនេះ។','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'រក្សាទុកលទ្ធផលបកប្រែពេញលេញក្នុងមួយប្រភេទមាត្រា។ ជាជម្រើស (បើបានបើកក្នុង Behavior)។ ជួយល្បឿនការបកប្រែជារឿយៗនៃមាត្រាដែលមិនផ្លាស់ប្តូរ។ លុបវានៅទីនេះពេលដែលអ្នកចង់បង្ខំឲ្យ AI ធ្វើការបង្វិលថ្មីមិនគិតថាមាត្រាបានផ្លាស់ប្តូរឬអត់។','Storytelling'=>'ការរៀបរាប់រឿង','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'របៀបរក្សាសិទ្ធិខ្ពស់សម្រាប់មាតិកាផ្នែកច្បាប់, ច្បាប់, វេជ្ជសាស្ត្រ ឬបច្ចេកទេស។ នៅពេលបើក, មុខងារ AI ទាំងអស់ប្រើសីតុណ្ហភាពសំណុំតិច និងភ្ជាប់បន្ថែមខាងក្រោមទៅក្នុងសំណើប្រព័ន្ធរបស់វា — ពាក្យបញ្ជា, លេខអត្ថបទ, ឯកតា, ឈ្មោះម៉ាក និងភាសាដែលត្រូវបានគោរពតាមពិតប្រាកដជាមិនត្រូវបានបំលែង។','Structured Outline'=>'រចនាសម្ព័ន្ធសេចក្ដីផ្តើម','Subdomain (de.example.com)'=>'ឧបសម្ព័ន្ធរង (de.example.com)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'របៀប subdomain ត្រូវការឲ្យម៉ាស៊ីនបម្រើវេបសាយរបស់អ្នកបញ្ជូន subdomains ភាសាទាំងអស់ (e.g. de.example.com) ទៅកាន់ការតំឡើង WordPress នេះ។ បន្ទាប់ពីផ្លាស់ប្តូររបៀប, សូមលុបចោលច្បាប់ permalink និងសម្អាត cache ណាមួយ។ ប្រសិនបើ URL ផ្ទះរបស់អ្នកមាន www (e.g. www.example.com), ប្រើ filter lf_base_domain ដើម្បីកំណត់ domain មិនមាន www ដើម្បីឲ្យ subdomains ត្រូវបានកសាងបានត្រឹមត្រូវ។','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'ដាក់ស្នើ URL នេះទៅកាន់ Google Search Console ជាមួយផែនទីសាយសំខាន់របស់អ្នក។','Submit to Reddit'=>'ដាក់ស្នើទៅ Reddit','Suggested meta description'=>'ការពិពណ៌នាផ្សាយមេតា​ដែលបានផ្តល់ជូន','Suggested title'=>'ចំណងជើងដែលបានផ្តល់ជូន','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'អ្នកផ្គត់ផ្គង់ដែលគាំទ្រ: Anthropic (Claude), OpenAI (GPT), Google (Gemini)។ ជ្រើសរើសអ្នកផ្គត់ផ្គង់សកម្មពី dropdown — មានអ្នកផ្គត់ផ្គង់មួយតែប៉ុណ្ណោះដែលត្រូវបានប្រើក្នុងពេលតែមួយ។ បញ្ចូលកូនសោ API សម្រាប់អ្នកផ្គត់ផ្គង់នោះដើម្បីបើកមុខងារ AI។','Suppressed: %s.'=>'បានបិទ: %s។','Switch to a post-name based structure in'=>'ផ្លាស់ទីទៅរចនាសម្ព័ន្ធផ្អែកលើឈ្មោះអត្ថបទក្នុង','System'=>'ប្រព័ន្ធ','System Tab'=>'ផ្ទាំងប្រព័ន្ធ','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, សម្រាប់មុខងារ','Tag'=>'ស្លាក','Tags emitted'=>'ស្លាកដែលបានបញ្ចេញ','Target lang'=>'ភាសាគោល','Target Language'=>'ភាសាគោល','Target language'=>'ភាសាគោល','Target term'=>'ពាក្យគោល','Target: 140–160 chars for optimal SERP display'=>'គោលដៅ៖ 140–160 តួអក្សរសម្រាប់ការបង្ហាញលើ SERP យ៉ាងមានប្រសិទ្ធភាព','Technical'=>'បច្ចេកទេស','Technical / Scientific'=>'បច្ចេកទេស / វិទ្យាសាស្ត្រ','Technical / Scientific instructions'=>'ការណែនាំបច្ចេកទេស / វិទ្យាសាស្ត្រ','Template "%s" already exists.'=>'"%s" មានរួចហើយ។','Template "{expected}" does not exist — create it in the Site Editor first.'=>'គំរូ "{expected}" មិនមាន — សូមបង្កើតវាក្នុងកម្មវិធីកែសម្រួលតំបន់បណ្តាញជាមុន។','Template has no content.'=>'គំរូមិនមានមាតិកា។','Template mode'=>'របៀបគំរូ','Template not found or not stored in the database.'=>'គំរូមិនមានឬមិនបានរក្សាទុកក្នុងមូលដ្ឋានទិន្នន័យ។','Template part "%s" already exists.'=>'ផ្នែកគំរូ "%s" មានរួចហើយ។','Template part has no content.'=>'ផ្នែកគំរូមិនមានមាតិកា។','Template part not found or not stored in the database.'=>'ផ្នែកគំរូមិនមានឬមិនបានរក្សាទុកក្នុងមូលដ្ឋានទិន្នន័យ។','Template Parts'=>'ផ្នែកគំរូ','Templates'=>'គំរូ','Test connection'=>'សាកល្បងការតភ្ជាប់','Testing…'=>'កំពុងសាកល្បង…','Text domain / locale'=>'ដែនភាសា / ភាសា','Text to translate'=>'អត្ថបទដែលត្រូវបកប្រែ','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'ឃ្លាំងចម្លើយ API រក្សាទុកលទ្ធផលដើមនៃសំណើរ AI រាល់ការស្នើសុំ — ការប្រែសម្រួល, ការពិពណ៌នាផ្សេងៗ, សេចក្ដីសង្ខេប និងការបង្កើតមាតិកា — ត្រូវបានគេផ្ដល់ដោយ hash នៃការបញ្ចូល (មាតិកា, គូភាសា, ផ្គត់ផ្គង់, ម៉ូដែល)។ បិទវាពេលកំពុងកែសម្រួល prompt ឬពេលដែលអ្នកត្រូវការឲ្យសំណើរ​ទៅដល់ AI។ ការបិទមិនលុបចោលឯកតាដែលបានរក្សាទុក — ការបើកវិញនឹងស្ដារឡើងវិញ។','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'បរិមាណប្រចាំថ្ងៃ (កំណត់ក្នុង Behavior → Limits) ត្រូវបានតាមដាននៅទីនេះ។ ពេលដែលបរិមាណប្រើប្រាស់បានសម្រេច, ការហៅ AI ត្រូវបានផ្អាកសម្រាប់ថ្ងៃស restante។ តារាងបង្ហាញថាបានប្រើប្រាស់ប៉ុន្មាន។','The editor did not accept the content — please try again.'=>'កែប្រែដោយកែប្រែ មិនទទួលយកមាតិកា — សូមព្យាយាមម្តងទៀត។','The following directive is active in your virtual robots.txt:'=>'ការណែនាំខាងក្រោមមានសកម្មក្នុង robots.txt វិចិត្រសាលរបស់អ្នក៖','The lf-social-share mu-plugin is active.'=>'កម្មវិធី mu-plugin lf-social-share សកម្ម។','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'កម្មវិធី mu-plugin lf-social-share សកម្ម។ Lingua Forge\'s built-in Social Share មិនសកម្មទេ — កម្មវិធី mu-plugin គ្រប់គ្រងការកែប្រែ URL ចែករំលែក និងសកម្មភាព JS។','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'កម្រិតពន្លឺប្រើម៉ូដែលលឿនដែលបានកំណត់ក្នុងតារាងម៉ូដែលខាងលើ (លំនាំដើម: Haiku / Flash)។ ប្ដូរទៅកម្រិតគុណភាព ប្រសិនបើអ្នកត្រូវការពិនិត្យត្រឹមត្រូវដូចគ្នានៅក្នុងរបៀបទំព័រពេញសម្រាប់ខ្លឹមសារ។','The phrase as it appears in the source text.'=>'ប្រយោគដូចដែលវាបង្ហាញក្នុងអត្ថបទប្រភព។','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'ភាសាចម្បងតែងតែត្រូវបានបម្រើនៅផ្ទៃដើមនៃគេហទំព័ររបស់អ្នក — គ្មាន URL prefix នៅក្នុងរបៀបផ្លូវ, គ្មាន subdomain ភាសា នៅក្នុងរបៀប subdomain។ ភាសាផ្សេងទៀតប្រើ either a /lang/ path prefix (e.g. example.com/de/) ឬ a language subdomain (e.g. de.example.com), អាស្រ័យលើការកំណត់រចនាសម្ព័ន្ធ URL ខាងក្រោម។','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'ផ្ទាំង SEO → Compatibility បង្ហាញស្ថានភាពការរកឃើញបន្តផ្ទាល់ និងពន្យល់ច្បាស់ថា LF កំពុងធ្វើអ្វីសម្រាប់តំបន់មុខងារ។','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'URL ចែករំលែកតែងតែបញ្ចេញភាពបច្ចុប្បន្ននៃទំព័រ — មិនចាំបាច់បញ្ចូល URL ដោយដៃទេ។ តម្រង linguaforge_social_share_url អាចប្តូរវិញ URL ដែលបានដោះស្រាយសម្រាប់សេវាកម្មណាមួយ។','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Sitemap ត្រូវបានប្រកាសក្នុង robots.txt ដោយស្វ័យប្រវត្តិ។ ប្រព័ន្ធស្វែងរកសំខាន់ៗទាំងអស់ — Google, Bing, Yandex — ស្វែងរកវាពី robots.txt។ មិនចាំបាច់ដាក់ស្នើដោយដៃទេ។','The source page has no footnotes.'=>'ទំព័រខ្សែប្រភពមិនមានចំណុចសម្គាល់។','The upload failed — please try again.'=>'ការផ្ទុកបរាជ័យ — សូមព្យាយាមម្តងទៀត។','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'តារាងការប្រើប្រាស់បង្ហាញការប្រើប្រាស់ token AI ត្រូវបានបែងចែកតាមលក្ខណៈពិសេស (ការបកប្រែ, ពិពណ៌នាមេតា, អត្ថបទខ្លី, គំរូ FSE, វិភាគជាក្រុម), អ្នកផ្គត់ផ្គង់, និងម៉ូដែល។ ប្រើប៊ូតុងកាលបរិច្ឆេទដើម្បីច្រានចោលតាមថ្ងៃនេះ, 7 ថ្ងៃចុងក្រោយ, 30 ថ្ងៃចុងក្រោយ, ឬទាំងអស់។','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Sitemap មូលដ្ឋាន WordPress បង្ហាញ URL របស់មាតិការបស់អ្នកទាំងអស់។ Sitemap LF បង្ហាញឲ្យម៉ាស៊ីនស្វែងរកដឹងពីរបៀបដែលកំណែភាសាខ្លួនផ្ទាល់ទាក់ទងគ្នាតាមរយៈ xhtml:link hreflang។ ដាក់ស្នើទាំងពីរទៅ Google Search Console សម្រាប់ការគ្រប់គ្រងពេញលេញ។','The WordPress site language (%1$s) is not among the active Lingua Forge content languages (%2$s). This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'ភាសាគេហទំព័រ WordPress (%1$s) មិនមែនជាភាសាអត្ថបទសកម្មក្នុងចំណោមភាសាអត្ថបទសកម្ម (%2$s)។ នេះបណ្តាលឲ្យសំណួរផលិតផល WooCommerce មិនមានលទ្ធផលទេ, រូបភាពផលិតផលបរាជ័យ, និងសំណួរទាំងអស់ដែលត្រូវបានត្រង់ភាសា។','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'ភាសា​គេហទំព័រ WordPress (ការកំណត់ → ទូទៅ → ភាសា​គេហទំព័រ) ត្រូវតែកំណត់ទៅមួយក្នុងចំណោមភាសាដែលអ្នកប្រើសម្រាប់មាតិកា — ឬភាសាមេរបស់មាតិកា ឬមួយក្នុងចំណោមភាសាឧទ្ទេស។ វាមិនអាចជាភាសាដែលមិនមានមាតិកានៅលើគេហទំព័រ។','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'ចំណុចសម្គាល់ទាំងនេះមកពីទំព័រខ្សែប្រភព ហើយត្រូវបានបង្ហាញនៅទីនេះសម្រាប់យោងតែប៉ុណ្ណោះ។ បន្ថែមវាទៅក្នុងទំព័រនេះដោយប្រើកម្មវិធីកែសម្រួលប្លុក។','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'បញ្ជីនេះត្រូវបានធ្វើឱ្យទាន់សម័យជាមួយការចេញផ្សាយ Lingua Forge មួយៗ។ ការធ្វើតេស្តការតភ្ជាប់នៅក្នុងផ្ទាំងកូនសោ API ក៏ទាញយកបញ្ជីម៉ូដែលផ្សាយបន្តផ្ទាល់ពីអ្នកផ្គត់ផ្គង់ និងធ្វើឱ្យបញ្ជីណែនាំខាងលើទាន់សម័យ។','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'នេះគឺជាទំព័រពីប្រព័ន្ធ WooCommerce (ហាង, កាត, ការទូទាត់, ល។)។ មាតិការបស់វាត្រូវបានគ្រប់គ្រងដោយ WooCommerce — ពិន្ទុបង្ហាញសញ្ញាសម្ព័ន្ធតែប៉ុណ្ណោះ មិនមែនមាតិកា SEO ដែលអាចកែប្រែបានដោយអ្នកប្រើ។','This is the source page. Footnotes are edited directly in the block editor.'=>'នេះគឺជាទំព័រខ្សែប្រភព។ កំណត់ចំណុចសម្គាល់ត្រូវបានកែសម្រួលដោយផ្ទាល់ក្នុងកម្មវិធីកែសម្រួលប្លុក។','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'កូនសោនេះផ្គត់ផ្គង់ដោយម៉ាស៊ីនមេ %s ហើយមិនអាចយកចេញនៅទីនេះទេ។ បញ្ចូលកូនសោថ្មីខាងលើដើម្បីជំនួសវាជាមួយតម្លៃក្នុងមូលដ្ឋានទិន្នន័យ។','This language is protected and cannot be uninstalled.'=>'ភាសានេះមានការពារ ហើយមិនអាចដំឡើងចេញបាន។','This language matches the WordPress instance locale and cannot be uninstalled.'=>'ភាសានេះផ្គូផ្គងនឹងទីតាំង WordPress ហើយមិនអាចដំឡើងចេញបាន។','Tier'=>'កម្រិត','Tip: to reset a model to the built-in default, clear the field and save.'=>'គន្លឹះ: ដើម្បីកំណត់ម៉ូដែលទៅលើលំនាំដើម បើកវាល និងរក្សាទុក។','Title'=>'ចំណងជើង','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'ចំណងជើង 15 ពិន្ទុ · ពិពណ៌នាផ្សាយ 20 ពិន្ទុ · ចំនួនពាក្យ 15 ពិន្ទុ · ចំណងជើង 20 ពិន្ទុ · រូបភាព 10 ពិន្ទុ · តំណភ្ជាប់ 10 ពិន្ទុ។ កំណត់ហេតុ SERP ចំណងជើង 60 តួអក្សរ; ពិពណ៌នា 120–210 តួអក្សរ; ការព្រមានចំនួនពាក្យក្រោម 300, បរាជ័យក្រោម 100; តម្រូវ H2; តម្រូវតំណភ្ជាប់ក្នុងស្រុក។','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'ចំណងជើងគឺ %1$d តួអក្សរ — អាចត្រូវបានកាត់ខ្លីក្នុង SERPs (ព្យាយាមក្រោម %2$d)។','Title is only %d chars — aim for at least 10 characters.'=>'ចំណងជើងមានតែ %d តួអក្សរប៉ុណ្ណោះ — ព្យាយាមឱ្យមានយ៉ាងហោចណាស់ ១០ តួអក្សរ។','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'ច្បាប់ពិន្ទុចំណងជើង (គ្រប់ប្រវត្តិរូប): បរាជ័យបើវាអត់មាន; ព្រមានបើមានតួអក្សរតិចជាង 10; ព្រមានបើមានពាក្យតែមួយ; ព្រមានបើវាយតាមកំណត់ SERP (60 តួអក្សរសម្រាប់ Blog, 70 សម្រាប់ផលិតផល/Landing); ត្រូវប្រសិនបើមានតួអក្សរយ៉ាងហោចណាស់ 10, មានពាក្យយ៉ាងហោចណាស់ 2, និងនៅក្នុងកម្រិត SERP។','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'ដើម្បីប្រើសម្ងាត់ការអ៊ិនគ្រីបផ្ទាល់ខ្លួន (ជំនួសតម្លៃ wp_salt ដែលបានយកមកពីមុខ), បន្ថែមនេះទៅក្នុង wp-config.php:','Today'=>'ថ្ងៃនេះ','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'ការប្រើប្រាស់ Token ត្រូវបានរាប់បញ្ចូលតាមលក្ខណៈពិសេស អ្នកផ្គត់ផ្គង់ និងម៉ូដែល។ បានកត់ត្រានៅលើការហៅ AI ជោគជ័យរាល់ដង; ការតេស្តការតភ្ជាប់ត្រូវបានដកចេញដើម្បីមិនប៉ះពាល់ចំនួនសរុប។','Token usage'=>'ការប្រើប្រាស់ Token','Tone'=>'សម្លេង','tone'=>'សម្លេង','Tone:'=>'សម្លេង៖','Too many AI requests. Please retry in %d seconds.'=>'សំណើរអាយអាយច្រើនពេក។ សូមព្យាយាមម្តងទៀតក្នុង %d វិនាទី។','Total'=>'សរុប','Total tokens'=>'Token សរុប','Translate'=>'បកប្រែ','Translate / Revise'=>'បកប្រែ / កែសម្រួល','Translate / Revise block'=>'បកប្រែ / កែសម្រួលផ្ទាំង','Translate all'=>'បកប្រែទាំងអស់','Translate all %s terms (AI)'=>'បកប្រែពាក្យ %s ទាំងអស់ (AI)','Translate all categories (AI)'=>'បកប្រែប្រភេទទាំងអស់ (AI)','Translate all labels (AI)'=>'បកប្រែស្លាកសញ្ញាទាំងអស់ (AI)','Translate all tags (AI)'=>'បកប្រែស្លាកសញ្ញាទាំងអស់ (AI)','Translate all terms (AI)'=>'បកប្រែពាក្យទាំងអស់ (AI)','Translate chunk'=>'បកប្រែផ្នែកចេញ','Translate Content'=>'បកប្រែមាតិកា','Translate missing'=>'បកប្រែអស់ចោល','Translate page…'=>'បកប្រែទំព័រ…','Translated content'=>'មាតិកាបកប្រែ','Translated Labels'=>'ស្លាកសញ្ញាដែលបានបកប្រែ','Translated Names'=>'ឈ្មោះដែលបកប្រែ','Translated title'=>'ចំណងជើងដែលបានបកប្រែ','Translated to:'=>'បកប្រែទៅជា៖','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'បានបកប្រែ។ ពិនិត្យឡើងវិញនៅក្នុងអ្នកកែសម្រួលតំបន់បណ្តាញ — តំណភ្ជាប់ក្នុងផ្ទៃ និង URL នាវីហ្គេសិន និងស្លាកស្លាកគំរូមិនត្រូវបានធ្វើឱ្យទាន់សម័យដោយស្វ័យប្រវត្តិទេ។','Translating…'=>'កំពុងបកប្រែ…','Translation Caching'=>'ការចងចាំការប្រែសម្រួល','Translation caching'=>'ការចងចាំការបកប្រែ','Translation failed. Check the browser console.'=>'ការបកប្រែបរាជ័យ។ សូមពិនិត្យកុងសូលរបស់កម្មវិធីរុករក។','Translation found but permalink could not be generated'=>'បានរកឃើញការបកប្រែ ប៉ុន្តែមិនអាចបង្កើត permalink បាន។','Translation Limits'=>'កំណត់ការប្រែប្រែ','Translation Limits & Behavior'=>'ដែនកំណត់និងអាកប្បកិរិយាការប្រែសម្រួល','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'ដែនកំណត់ការប្រែសម្រួល៖ គ្រប់គ្រងតួនាទីអ្នកប្រើប្រាស់ដែលអាចបើកប្រើការប្រែសម្រួល AI និងកំណត់ថវិកាការប្រើប្រាស់សេវាកម្មប្រចាំខែ។ ការប្រើប្រាស់លើសថវិកានឹងផ្អាកការហៅ AI រហូតដល់ខែថ្មី។','Translation Memory'=>'អង្គចងចាំការប្រែសម្រួល','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'អង្គចងចាំការប្រែសម្រួលរក្សាទុកលទ្ធផល AI តាមការចងចាំមាតិកា, គូភាសា, អ្នកផ្គត់ផ្គង់ និងម៉ូដែល។ ការកែសម្រួលអត្ថបទមួយនឹងធ្វើអោយការចងចាំមិនមានសុពលភាព ដូច្នេះការហៅបន្ទាប់នឹងទទួលបានលទ្ធផលថ្មី។','Translation Memory cleared. %d cached block was removed.'=>'អង្គចងចាំការបកប្រែបានសម្អាត។ %d ប្លុកដែលបាន cache ត្រូវបានយកចេញ។' . "\0" . '','Translation Memory setting saved.'=>'ការកំណត់អង្គចងចាំការប្រែសម្រួលបានរក្សាទុក។','Translation workflow'=>'ដំណើរការប្រែសម្រួល','Translation, Content Generator'=>'ការប្រែសម្រួល, អ្នកបង្កើតមាតិកា','Treat H2 as H1 equivalent'=>'ចាត់ទុក H2 ជាសមាជិក H1','Type'=>'ប្រភេទ','Uli Hake'=>'Uli Hake','Unexpected provider error (HTTP %d).'=>'កំហុសអ្នកផ្គត់ផ្គង់មិនទៀងទាត់ (HTTP %d).','Uninstall %s'=>'ដំឡើងចេញ %s','Uninstall Behaviour'=>'ការដំឡើងវិធីសាស្ត្រ','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'អាកប្បកិរិយាការដំឡើងចោល: គ្រប់យ៉ាងដែលត្រូវបានលុបចេញនៅពេលដែលដកចេញកម្មវិធីពី Plugins → Plugins បានដំឡើង → លុប។ ការកំណត់កម្មវិធី និង cache AI តែងតែត្រូវបានលុបចេញ។ ការចាត់តាំងភាសា, ទំនាក់ទំនងការបកប្រែ, ការពិពណ៌នាផ្សេងៗ, វចនានុក្រម, និងចងចាំការបកប្រែ ត្រូវបានរក្សាទុកដោយលំនាំដើម ដូច្នេះការដំឡើងឬដំឡើងវិញដោយសេរីអាចបន្តពីទីនោះ។ បើក "លុបទិន្នន័យមាតិកាលើការដំឡើងចោល" តែពេលដែលអ្នកកំពុងលុបចោលការគាំទ្រភាសពហុភាសាពេញលេញពីគេហទំព័រ — នេះមិនអាចត្រឡប់វិញបាន។','Uninstall setting saved.'=>'ការកំណត់លុបកម្មវិធីត្រូវបានរក្សាទុក។','unknown error'=>'កំហុសមិនស្គាល់','Unknown provider.'=>'អ្នកផ្គត់ផ្គង់មិនស្គាល់។','Unknown search engine.'=>'ម៉ាស៊ីនស្វែងរកមិនស្គាល់។','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'ខុសពី hreflang — ដែល LF តែងតែបដិសេធកម្មវិធីផ្សេងទៀតដោយសារតែពួកវាមិនអាចដឹងពីការកំណត់ភាសាច្រើនរបស់អ្នក — Open Graph ផ្សេងទៀត: Yoast, Rank Math និងកម្មវិធីផ្សេងទៀតបានបញ្ចេញ OG tags ត្រឹមត្រូវសម្រាប់មាតិការបស់អ្នក។ ការចម្លងពួកវាមិនមានតម្លៃ។ នៅក្នុងរបៀបស្វ័យប្រវត្តិ LF ស្គាល់កម្មវិធី SEO សកម្ម និងបន្ថែមតែអ្វីដែលពួកវាមិនអាចផ្តល់បាន: og:locale (ភាសាបច្ចុប្បន្ន) និង og:locale:alternate (ភាសាផ្សេងទៀតដែលបានកំណត់)។','Unlimited'=>'គ្មានកំណត់','Up'=>'ឡើង','Upload .mo file'=>'ផ្ទុកឯកសារ .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'ផ្ទុកឯកសារ .mo ដែលបានបញ្ចូលសម្រាប់បដិសេធសំណួរពីភាសាផ្សេងៗ — ឧទាហរណ៍, ការប្រែសម្រួល VikBooking ផ្ទាល់ខ្លួនដែលប្រើ "អាផាតមិន" ជំនួស "បន្ទប់"។ ឯកសារត្រូវតែអនុលោមនាមសញ្ញា WordPress: {textdomain}-{locale}.mo (ឧទាហរណ៍ vikbooking-ca.mo)។ វាត្រូវបានផ្ទុកក្នុងថត uploads ហើយអាចរស់នៅក្រោមការអាប់ដេតកម្មវិធីផ្លាស់ទី។','Upload Override'=>'ផ្ទុកឯកសារប្តូរ','URL could not be mapped to a post — check the link target exists'=>'URL មិនអាចផ្គូផ្គងទៅអត្ថបទបាន — សូមពិនិត្យមើលថាតើគោលដៅតំណភ្ជាប់មានទេឬទេ។','URL structure'=>'រចនាសម្ព័ន្ធ URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'រចនាសម្ព័ន្ធ URL៖ របៀបផ្តាច់ផ្លូវ (example.com/de/) មិនត្រូវការការផ្លាស់ប្តូរពីម៉ាស៊ីនមេ។ របៀបផ្តាច់ផ្លូវរង (de.example.com) ត្រូវការកំណត់ DNS ពីរបៀប, សំបុត្រសុវត្ថិភាព SSL ពីរបៀប និងការកំណត់ម៉ាស៊ីនមេ — សូមមើលមគ្គុទេសក៍ការរៀបចំម៉ាស៊ីនមេ។','URL to enter'=>'URL ដែលត្រូវបញ្ចូល','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'ប្រើការចែករំលែកក្នុងស្ថានភាពដើម; ត្រឡប់ទៅការចម្លងចេញពី Clipboard។ ជម្រើសលំនាំដើមសម្រាប់ប៊ូតុង "ចែករំលែក"។','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'ប្រើផ្ទាំងផ្ទាំងនៅលើផ្នែកខាងលើនៃទំព័រនេះដើម្បីកំណត់តំបន់នីមួយៗ។ ការផ្លាស់ប្តូរទៅផ្ទាំង Router មានផលប៉ះពាល់ភ្លាមៗ; ការផ្លាស់ប្តូរទៅកូនសោ AI និងការកំណត់ម៉ូដែលអនុវត្តនៅលើសំណើ AI បន្ទាប់។','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'តារាងពាក្យស្លាកដែលគ្រប់គ្រងដោយអ្នកប្រើក្នុងភាសាទីពីរ។ ការចុះបញ្ជីត្រូវបានបន្ថែមទៅក្នុងសំណើប្រព័ន្ធប្រែសម្រួល ដើម្បីឲ្យ AI ប្រើពាក្យពេចន៍ដែលចូលចិត្តយ៉ាងស្ថិតស្ថេរ — ពាក្យស្លាកសំខាន់សម្រាប់វចនានុក្រមវិស័យ ("kWp", "PPA", "ចំណុចការតភ្ជាប់"), ឈ្មោះម៉ាកដែលមិនត្រូវបកប្រែ, និងប្រយោគស្តង់ដារច្បាប់។ ទាំងពីរភាសាអាចជ្រើសរើសបាន៖ "Source language" និង "Target language"។','Using custom meta description.'=>'ប្រើការពិពណ៌នាមេតាខ្លួនឯង។','Using LF AI meta description.'=>'ប្រើ meta description AI របស់ LF។','Value source'=>'ប្រភពតម្លៃ','Version'=>'កំណែ','View'=>'មើល','View built-in default'=>'មើលលំនាំដើមដែលបានបង្កើត','View current robots.txt'=>'មើល robots.txt បច្ចុប្បន្ន','View details'=>'មើលព័ត៌មានលម្អិត','View Lingua Forge details'=>'មើលព័ត៌មានលម្អិត Lingua Forge','Visit plugin site'=>'ចូលទៅកាន់តំបន់បន្ថែម','Warning:'=>'ការព្រមាន៖','WcPageBridge active'=>'WcPageBridge ប្រើបាន','WebSite'=>'វេបសាយ','WebSite — front page / blog index'=>'វេបសាយ — ទំព័រមុខ / ប្លុកសន្ទស្សន៍','What LF provides — and collision avoidance'=>'អ្វីដែល LF ផ្តល់ — និងការជៀសវាងការប៉ះពាល់','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'អ្វីដែល LF ផ្តល់: ស្លាក hreflang សម្រាប់ភាសាណាមួយដែលបានកំណត់, ស្លាក Open Graph និង Twitter Card ជាមួយ og:locale និង og:locale:alternate, JSON-LD Schema.org ជាមួយការបែងចែក inLanguage, និង sitemap ភាសាច្រើនផ្ទាល់ខ្លួននៅ /lf-sitemap.xml ជាមួយចំណងជើង xhtml:link សម្រាប់ក្រុមបកប្រែទាំងអស់។','When another SEO plugin is installed'=>'នៅពេលមានកម្មវិធី SEO ផ្សេងទៀតដំឡើង','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'ពេលដែលមានការចាប់ផ្តើមកំណត់តាមដំណាក់កាល (តាមរយៈការបិទឬដោយកំណត់ LINGUAFORGE_AI_DEBUG នៅក្នុង wp-config.php) លក្ខណៈពិសេសបកប្រែ និងបកប្រែទំរង់ FSE សរសេរពាក្យសុំ AI និងចម្លើយរបស់ពួកវាទៅឯកសារសម្រាប់ការរកកំហុស។ ប្រើផ្នែកនេះដើម្បីតាមដានផលិតផលនោះ ហើយសម្អាតវាពេលដែលអ្នកមានអ្វីដែលត្រូវការ — ឯកសារអាចធំឡើងយ៉ាងឆាប់រហ័សនៅលើទំព័រធំ។ កំណត់ទីតាំងថតទិន្នន័យតាមរយៈតម្រង linguaforge_debug_dir។','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'ពេលដែលបានបើក, អ្នកទស្សនាដំបូងដែលមិនមាន cookie ភាសា និងមិនមាន prefix ភាសា នៅក្នុង URL ត្រូវបានបញ្ជូនទៅកាន់កំណត់ភាសាដែលសមនឹងជិតស្និទ្ធ។ ការបញ្ជូនត្រូវបានរំលង ប្រសិនបើភាសាដែលកម្មវិធីរុករកចូលចិត្តមិនមែនជាសមាជិកក្នុងភាសាដែលដំណើរការ។ បន្ទាប់ពីអ្នកទស្សនាជ្រើសរើសភាសាមួយតាម switcher, cookie នឹងមានអាទិភាព ហើយ header កម្មវិធីរុករកត្រូវបានមិនប្រើនៅលើការអានទស្សនាផ្សេងទៀត។','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'នៅពេលដែលបានបើកដំណើរការ LF ផ្តល់ស្លាក meta បន្ថែមដូចជា og:type=product, og:price:amount, og:price:currency, og:availability និងសមាជិកផលិតផលដែលប្រើដោយ Facebook Catalog។','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'នៅពេលដែលបានបើកដំណើរការ URL sitemap ត្រូវបានប្រកាសក្នុង robots.txt ដោយស្វ័យប្រវត្តិ ហើយ cache ត្រូវបានធ្វើឱ្យថ្មីនៅពេលដែលបានរក្សាទុកមាតិកាដែលបានបកប្រែ។','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'ពេលប្រវត្តិរូប Blog ត្រូវការជា H2 ហើយមិនមានអ្វីទេ អ្នកវិភាគចាប់ផ្តើមពិនិត្យមើលសម្រាប់ចំណងជើងរង H3 មុនពេលផ្តល់ការព្រមាន។ ប្លុក Accordion និង Details ដំណើរការជា H3 សម្រាប់ចំណងជើងរបស់ពួកវា; អ្នកទាំងនោះទទួលស្គាល់ថាជាស្ថាបត្យកម្មត្រឹមត្រូវ ហើយបង្កើតលទ្ធផល ok មិនមែនការព្រមាន។','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'ពេលភាសាគេហទំព័រ WP មិនមែនជាភាសាអត្ថបទ: សំណួរផលិតផល WooCommerce មិនបង្ហាញលទ្ធផលទេនៅលើប្លុកកាតាឡុកទាំងអស់; ការបែងចែករូបភាពផលិតផលបរាជ័យ; សំណួរអត្ថបទដែលត្រូវបានតម្រងភាសាបែកបាក់; អ្នកផ្លាស់ទីភាសាអាចបង្ហាញជម្រើសភាសាដែលមិនមែនជាអត្ថបទ។ ប្រសិនបើអ្នកឃើញការជូនដំណឹងកំណត់រចនាសម្ព័ន្ធពណ៌ក្រហមនៅលើផ្ទាំង Router ឬ System សូមកែសម្រួលភាសាគេហទំព័រឡើងវិញជាមុន។','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'នៅពេលដែល Yoast SEO, Rank Math, All in One SEO ឬ SEOPress មានសកម្ម, Lingua Forge ដោយស្វ័យប្រវត្តិបិទការចេញ hrelfang ដោយប្រើតម្រង។ កម្មវិធី SEO ទូទៅបង្កើត hreflang ពីរចំណង URL តែមួយ ហើយមិនអាចគណនាការរៀបចំផ្លូវរបស់អ្នកបានទេ; ការចេញផ្សាយរបស់ LF តែងតែត្រឹមត្រូវ។','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'កម្រិតម៉ូដែលដែលត្រូវប្រើសម្រាប់ការប្រែប្រែទំព័រពេញ។ គុណភាពប្រើម៉ូដែលដែលបានកំណត់ក្នុងតារាងម៉ូដែលខាងលើ ហើយត្រូវបានណែនាំសម្រាប់ការប្រែប្រែត្រឹមត្រូវ និងប្រវែងវែង។ ប្ដូរទៅ Light ប្រសិនបើល្បឿន ឬថ្លៃសមរម្យគឺជាចំណុចសំខាន់ និងមាតិកាខ្លី។','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'នៅពេលដែលមានសកម្ម, mu-plugin គ្រប់គ្រងសំណុំ OG មូលដ្ឋាន និង LF បញ្ចេញស្លាកភាសាទេ (របៀបស្វ័យប្រវត្តិ)។ ដកចេញវាប្តូរឲ្យ LF ទៅរបៀប OG ពេញដោយស្វ័យប្រវត្តិ។','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce មិនដំណើរការឡើយ។','WooCommerce page translations'=>'ការប្រែសម្រួលទំព័រ WooCommerce','WooCommerce product price'=>'តម្លៃផលិតផល WooCommerce','WooCommerce SEO settings saved.'=>'ការកំណត់ SEO របស់ WooCommerce បានរក្សាទុក។','WooCommerce store currency'=>'រូបិយប័ណ្ណហាង WooCommerce','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'ទំព័រពីប្រព័ន្ធ WooCommerce (ហាង, កាត, ការទូទាត់, គណនីរបស់ខ្ញុំ) ត្រូវបានដកចេញ — មាតិការបស់ពួកវាត្រូវបានគ្រប់គ្រងដោយ WooCommerce ហើយមិនអាចកែលម្អតាម SEO។','WooCommerce version'=>'កំណែ WooCommerce','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'កំណត់ត្រាសំណុំ WooCommerce, របៀបផ្ទុកសំណើរ (CPT / HPOS / ចែករំលែក), និងតារាងការគ្រប់គ្រងការបកប្រែតាមភាសាសម្រាប់ទំព័រ WC បួនដែលមានសមាជិក (ហាង, កាត, ការទូទាត់, គណនីរបស់ខ្ញុំ)។','Word count'=>'ចំនួនពាក្យ','WordPress version'=>'កំណែ WordPress','WP core canonical active (hreflang disabled)'=>'WordPress core canonical សកម្ម (hreflang មិនដំណើរការ)','WP instance language'=>'ភាសា WordPress','WP site language requirement'=>'តម្រូវការភាសាគេហទំព័រ WP','WP-CLI reference'=>'យោង WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'សរសេរពិចារណា AI និងចម្លើយទៅឯកសារដើម្បីជួយសម្រួលបញ្ហា','XML Sitemap'=>'XML Sitemap','Yes'=>'បាទ','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'អ្នកអាចកំណត់កូនសោជា អថេរ ឬ អថេរបរិស្ថាន (ឧទាហរណ៍នៅក្នុង wp-config.php)។ ប្រភពទាំងនេះត្រូវបានប្រើដោយស្វ័យប្រវត្តិជាការជំនួសនៅពេលដែលមិនមានកូនសោមូលដ្ឋានទិន្នន័យ។','You do not have permission to manage these settings.'=>'អ្នកមិនមានសិទ្ធិគ្រប់គ្រងការកំណត់ទាំងនេះទេ។','You do not have permission to read this post.'=>'អ្នកមិនមានសិទ្ធិអានអត្ថបទនេះទេ។','{n} stale path(s)'=>'{n} ផ្លូវចាស់ៗ','~%d min read'=>'~%d នាទីអាន' . "\0" . '','— AI features are disabled.'=>'— លក្ខណៈពិសេស AI ត្រូវបានបិទ។','— Any source language —'=>'— ប្រភពប្រភព —','— Any target language —'=>'— ភាសាគោល —','— Any target —'=>'— គោលណាមួយ —','— Any —'=>'— អ្វីៗ —','— Auto-detect —'=>'— ស្វ័យប្រវត្តិរកឃើញ —','— auto-detect —'=>'— ស្វែងរកដោយស្វ័យប្រវត្តិ —','— Deferred to plugin'=>'— បានផ្ទុកចុះទៅកម្មវិធីផ្គត់ផ្គង់','— Disabled'=>'— បានបិទ','— Not detected'=>'— មិនបានរកឃើញ','— select a language —'=>'— ជ្រើសរើសភាសា —','← Back'=>'← ត្រឡប់ក្រោយ','↑ Detected from current post'=>'↑ បានរកឃើញពីការបង្ហោះបច្ចុប្បន្ន','→ Locale tags only (manual setting)'=>'→ ស្លាកភាសាទេ (ការកំណត់ដោយដៃ)','→ Locale tags only — deferring base OG to plugin'=>'→ ស្លាកភាសាទេ — កំពុងផ្តល់ OG មូលដ្ឋានដោយកម្មវិធីផ្គត់ផ្គង់','↺ Re-translate'=>'↺ ប្រែសម្រួលម្ដងទៀត','↺ Refine'=>'↺ កែលម្អ','↺ Refresh'=>'↺ ធ្វើឱ្យស្ទើរ','↺ Refresh AI Analysis'=>'↺ បន្ថែមវិភាគ AI','↺ Refreshing…'=>'↺ កំពុងធ្វើស្កេនឡើងវិញ…','⚠ Borderline'=>'⚠ ពីចន្លោះ','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ មិនមានអត្ថបទ <strong>{lang}</strong> ទេ។ សូមប្រាកដថាអត្ថបទទាំងអស់ដែលបានបកប្រែមានការកំណត់ភាសា <strong>{lang}</strong> នៅក្នុងប្រអប់ភាសា។','⚠ No changes'=>'⚠ មិនមានការផ្លាស់ប្តូរ','⚠ No changes — re-scan?'=>'⚠ មិនមានការផ្លាស់ប្តូរ — ស្កេនឡើងវិញទេ?','✅ Fixed ({n})'=>'✅ បានជួសជុល ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ មិនមានតំណភ្ជាប់ខូចឬការខុសគំរូទេសម្រាប់ <strong>{lang}</strong>។ បានស្កេនអត្ថបទ និងទំព័រ <strong>{scanned}</strong> ទាំងអស់ — ពិនិត្យទាំងអស់បានជោគជ័យ។ តំណភ្ជាប់ផ្នែកគំរូ (ក្បាល, ផ្នែកខាងក្រោម, ផ្នែកខាងស្តាំ) មិនត្រូវបានរួមបញ្ចូលនៅទីនេះ — ប្រើប៊ូតុងកែសម្រួលកំណត់គំរូដើម្បីពិនិត្យវាឡើងវិញ។','✅ Template fixed'=>'✅ Templates បានជួសជុល','✓ %s notified successfully.'=>'✓ %s បានជូនដំណឹងដោយជោគជ័យ។','✓ Active'=>'✓ សកម្មភាព','✓ Active at /lf-sitemap.xml'=>'✓ សកម្មភាពនៅ /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ សកម្មភាព — %d បញ្ជី URL ជាមួយជម្រើសភាសា' . "\0" . '','✓ Active — full OG + Twitter Cards'=>'✓ សកម្មភាព — OG ពេញ + កាត Twitter','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ សកម្មភាព — ស្លាកភាសាតែ (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ ផ្នែកទាំងអស់ត្រូវបានបង្កើត។','✓ All templates created.'=>'✓ គំរូទាំងអស់ត្រូវបានបង្កើត។','✓ All translated.'=>'✓ បានបកប្រែទាំងអស់។','✓ Configured'=>'បានកំណត់រួចហើយ','✓ Connection OK'=>'✓ ការតភ្ជាប់បានសម្រេច','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ មាតិកាបានបង្កើតហើយ — សូមមើលផ្ទាំងលើដើម្បីពិនិត្យ សម្រួល និងអនុវត្ត។','✓ Done'=>'✓ បានបញ្ចប់','✓ Enabled'=>'✓ បានបើក','✓ Good length'=>'✓ ប្រវែងល្អ','✓ Hreflang active'=>'✓ Hreflang សកម្មភាព','✓ In safe storage'=>'✓ នៅក្នុងសុវត្ថិភាព','✓ Language installed.'=>'✓ ភាសាត្រូវបានដំឡើង។','✓ LF outputs'=>'✓ ផលិតផល LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ ផលិតផល LF អត្ថបទ / WebPage / WebSite','✓ LF outputs full OG + Twitter Cards'=>'✓ ផលិតផល LF ពេញ OG + កាត Twitter','✓ LF outputs — plugin hreflang suppressed'=>'✓ ផលិតផល LF — ការចុះបញ្ជី hreflang ត្រូវបានបិទ','✓ Links fixed.'=>'✓ តំណភ្ជាប់ត្រូវបានជួសជុល។','✓ Nav refs fixed.'=>'✓ ការជួសជុលយោងនាវីហ្គេសិនត្រូវបានកំណត់។','✓ Parts fixed.'=>'✓ ផ្នែកត្រូវបានជួសជុល។','✓ Pattern translated.'=>'✓ គំរូត្រូវបានបកប្រែ។','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ ឯកសារ robots.txt ផ្ទាល់បានរកឃើញ។ ការណែនាំ Sitemap របស់ LF មានស្រេច។','✓ Refined — review the updated draft above.'=>'✓ បានកែលម្អ — សូមពិនិត្យសេចក្ដីព្រាងដែលបានធ្វើបច្ចុប្បន្នភាពខាងលើ។','✓ Translation saved'=>'✓ ប្រែសម្រួលបានរក្សាទុក','✓ WP core canonical removed'=>'✓ ការលុប canonical មូលដ្ឋាន WP','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s បានបរាជ័យ។ URL សាយតមិនបានប្រកាសនៅក្នុង robots.txt — ម៉ាស៊ីនស្វែងរកនឹងរកឃើញវានៅលើការរុករកបន្ទាប់របស់វា។','✗ Disabled'=>'✗ បានបិទ','✗ Error:'=>'✗ កំហុស៖','✗ Failed:'=>'✗ បរាជ័យ៖','✗ Not configured'=>'មិនបានកំណត់','✗ Too long'=>'✗ យូរពេក','✗ Too short'=>'✗ ខ្លីពេក','❌ Failed'=>'❌ បរាជ័យ','📄 Wrong template'=>'📄 គំរូមិនត្រឹមត្រូវ','📍 Stale path (page moved)'=>'📍 ផ្លូវចាស់ (ទំព័របានផ្លាស់ទី)']];
